CREATE OR REPLACE FUNCTION public.create_notification_preferences()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  INSERT INTO notification_preferences (user_id)
  VALUES (NEW.id)
  ON CONFLICT (user_id) DO NOTHING;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.bump_conversation_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  UPDATE conversations
  SET updated_at = now()
  WHERE id = NEW.conversation_id;
  RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public._login_email_for_username(p_username text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_name text := trim(coalesce(p_username, ''));
  v_email text;
  v_n int;
begin
  if length(v_name) < 3 or length(v_name) > 40 then
    return null;
  end if;
  select email into v_email from public.profiles
   where user_name = v_name and status = 'active'
   limit 1;
  if v_email is not null then
    return v_email;
  end if;
  select count(*), min(email) into v_n, v_email from public.profiles
   where lower(user_name) = lower(v_name) and status = 'active';
  if v_n = 1 then
    return v_email;
  end if;
  return null;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.get_auth_session()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  result jsonb;
  user_profile jsonb;
  user_id_auto integer;
  owned_ids jsonb;
  directed_ids jsonb;
BEGIN
  -- 1. Get the full profile row
  SELECT to_jsonb(p.*)
  INTO user_profile
  FROM profiles p
  WHERE p.id = auth.uid();

  -- No profile yet (new signup) → return null session
  IF user_profile IS NULL THEN
    RETURN jsonb_build_object(
      'profile', null,
      'owned_venue_ids', '[]'::jsonb,
      'directed_venue_ids', '[]'::jsonb
    );
  END IF;

  -- 2. Grab id_auto for venue lookups
  user_id_auto := (user_profile->>'id_auto')::integer;

  -- 3. Get venue IDs this user OWNS (bar owners)
  SELECT coalesce(jsonb_agg(vo.venue_id), '[]'::jsonb)
  INTO owned_ids
  FROM venue_owners vo
  WHERE vo.owner_id = user_id_auto
    AND vo.archived_at IS NULL;

  -- 4. Get venue IDs this user DIRECTS (tournament directors)
  SELECT coalesce(jsonb_agg(vd.venue_id), '[]'::jsonb)
  INTO directed_ids
  FROM venue_directors vd
  WHERE vd.director_id = user_id_auto
    AND vd.archived_at IS NULL;

  -- 5. Build the session object
  result := jsonb_build_object(
    'profile', user_profile,
    'owned_venue_ids', owned_ids,
    'directed_venue_ids', directed_ids
  );

  RETURN result;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.generate_recurring_tournaments()
 RETURNS TABLE(template_id integer, dates_inserted integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  tmpl          RECORD;
  horizon_end   DATE;
  check_date    DATE;
  day_num       INT;
  step_days     INT;
  inserted      INT;
  nth           INT;
  month_start   DATE;
  candidate     DATE;
  m             INT;
BEGIN
  FOR tmpl IN
    SELECT *
    FROM tournament_templates
    WHERE status = 'active'
      AND recurrence_type IS NOT NULL
      AND recurrence_day  IS NOT NULL
  LOOP
    inserted    := 0;
    horizon_end := CURRENT_DATE + COALESCE(tmpl.horizon_days, 30);

    -- Respect optional series end date
    IF tmpl.series_end_date IS NOT NULL AND tmpl.series_end_date < horizon_end THEN
      horizon_end := tmpl.series_end_date;
    END IF;

    -- Map recurrence_day text → DOW integer (0=Sun … 6=Sat)
    day_num := CASE lower(tmpl.recurrence_day)
      WHEN 'sunday'    THEN 0
      WHEN 'monday'    THEN 1
      WHEN 'tuesday'   THEN 2
      WHEN 'wednesday' THEN 3
      WHEN 'thursday'  THEN 4
      WHEN 'friday'    THEN 5
      WHEN 'saturday'  THEN 6
      ELSE 1
    END;

    -- --------------------------------------------------------
    -- WEEKLY / BIWEEKLY
    -- --------------------------------------------------------
    IF tmpl.recurrence_type IN ('weekly', 'biweekly') THEN
      step_days := CASE tmpl.recurrence_type WHEN 'biweekly' THEN 14 ELSE 7 END;

      -- Start from series_start_date, walk to the first matching weekday
      check_date := tmpl.series_start_date;
      WHILE EXTRACT(DOW FROM check_date)::INT <> day_num LOOP
        check_date := check_date + 1;
      END LOOP;

      -- Generate all occurrences in the window
      WHILE check_date <= horizon_end LOOP
        IF check_date >= CURRENT_DATE THEN
          IF NOT EXISTS (
            SELECT 1 FROM tournaments
            WHERE tournaments.template_id = tmpl.id
              AND tournament_date = check_date
          ) THEN
            INSERT INTO tournaments (
              venue_id, director_id, template_id, parent_template_id,
              name, description, description_es,
              game_type, tournament_format, game_spot, race, table_size,
              equipment, number_of_tables,
              tournament_date, start_time, timezone,
              entry_fee, added_money, side_pots,
              max_fargo, required_fargo_games, reports_to_fargo, open_tournament,
              phone_number, thumbnail, is_recurring, status,
              chip_ranges, calcutta
            ) VALUES (
              tmpl.venue_id, tmpl.director_id, tmpl.id, tmpl.id,
              tmpl.name, tmpl.description, tmpl.description_es,
              tmpl.game_type, tmpl.tournament_format, tmpl.game_spot, tmpl.race, tmpl.table_size,
              tmpl.equipment, tmpl.number_of_tables,
              check_date, tmpl.start_time, 'America/Phoenix',
              tmpl.entry_fee, tmpl.added_money, tmpl.side_pots,
              tmpl.max_fargo, tmpl.required_fargo_games, tmpl.reports_to_fargo, tmpl.open_tournament,
              tmpl.phone_number, tmpl.thumbnail, true, 'active',
              tmpl.chip_ranges, tmpl.calcutta
            );
            inserted := inserted + 1;
          END IF;
        END IF;
        check_date := check_date + step_days;
      END LOOP;

    -- --------------------------------------------------------
    -- MONTHLY  (Nth weekday of month, e.g. "3rd Friday")
    -- --------------------------------------------------------
    ELSIF tmpl.recurrence_type = 'monthly' THEN
      nth := COALESCE(tmpl.recurrence_week, 1);

      FOR m IN 0..23 LOOP
        month_start := DATE_TRUNC('month',
          tmpl.series_start_date + (m * INTERVAL '1 month'))::DATE;

        -- Find first occurrence of day_num in this month
        candidate := month_start;
        WHILE EXTRACT(DOW FROM candidate)::INT <> day_num LOOP
          candidate := candidate + 1;
        END LOOP;
        -- Advance to the Nth occurrence
        candidate := candidate + ((nth - 1) * 7);

        -- Skip if it rolled into the next month (e.g. "5th Friday" in a short month)
        IF EXTRACT(MONTH FROM candidate) <> EXTRACT(MONTH FROM month_start) THEN
          CONTINUE;
        END IF;

        EXIT WHEN candidate > horizon_end;

        IF candidate >= tmpl.series_start_date
           AND candidate >= CURRENT_DATE
           AND candidate <= horizon_end THEN
          IF NOT EXISTS (
            SELECT 1 FROM tournaments
            WHERE tournaments.template_id = tmpl.id
              AND tournament_date = candidate
          ) THEN
            INSERT INTO tournaments (
              venue_id, director_id, template_id, parent_template_id,
              name, description, description_es,
              game_type, tournament_format, game_spot, race, table_size,
              equipment, number_of_tables,
              tournament_date, start_time, timezone,
              entry_fee, added_money, side_pots,
              max_fargo, required_fargo_games, reports_to_fargo, open_tournament,
              phone_number, thumbnail, is_recurring, status,
              chip_ranges, calcutta
            ) VALUES (
              tmpl.venue_id, tmpl.director_id, tmpl.id, tmpl.id,
              tmpl.name, tmpl.description, tmpl.description_es,
              tmpl.game_type, tmpl.tournament_format, tmpl.game_spot, tmpl.race, tmpl.table_size,
              tmpl.equipment, tmpl.number_of_tables,
              candidate, tmpl.start_time, 'America/Phoenix',
              tmpl.entry_fee, tmpl.added_money, tmpl.side_pots,
              tmpl.max_fargo, tmpl.required_fargo_games, tmpl.reports_to_fargo, tmpl.open_tournament,
              tmpl.phone_number, tmpl.thumbnail, true, 'active',
              tmpl.chip_ranges, tmpl.calcutta
            );
            inserted := inserted + 1;
          END IF;
        END IF;
      END LOOP;
    END IF;

    -- Return summary row for this template
    template_id    := tmpl.id;
    dates_inserted := inserted;
    RETURN NEXT;
  END LOOP;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.search_players(p_query text, p_limit integer DEFAULT 20)
 RETURNS TABLE(id uuid, id_auto bigint, user_name text, name text, first_name text, last_name text, avatar_url text, home_state text, fargo integer, fargo_status text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_q text := trim(coalesce(p_query, ''));
  v_pat text;
begin
  if auth.uid() is null then
    raise exception 'not authenticated' using errcode = '42501';
  end if;
  if length(v_q) < 2 then
    return;
  end if;
  -- literal match: escape LIKE wildcards in the user's input
  v_pat := '%' || replace(replace(replace(v_q, '\', '\\'), '%', '\%'), '_', '\_') || '%';
  return query
    select p.id, p.id_auto, p.user_name, p.name, p.first_name, p.last_name,
           p.avatar_url, p.home_state, p.fargo, p.fargo_status
      from public.profiles p
     where p.status = 'active'
       and coalesce(p.is_disabled, false) = false
       and (p.user_name ilike v_pat or p.name ilike v_pat
            or p.first_name ilike v_pat or p.last_name ilike v_pat
            or (coalesce(p.first_name, '') || ' ' || coalesce(p.last_name, '')) ilike v_pat)
     order by p.user_name
     limit least(greatest(coalesce(p_limit, 20), 1), 50);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.cleanup_old_alert_matches(days_to_keep integer DEFAULT 90)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
DECLARE
  deleted_count INTEGER;
BEGIN
  DELETE FROM alert_matches 
  WHERE created_at < (now() - INTERVAL '%s days', days_to_keep);
  
  GET DIAGNOSTICS deleted_count = ROW_COUNT;
  RETURN deleted_count;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.delete_user_account()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid        uuid   := auth.uid();
  v_id_auto    bigint;
  v_role       text;
  v_conv_ids   uuid[];
  v_msg_ids    int[];
  v_nmsg_ids   uuid[];
  v_player_ids uuid[];
  v_big_ids    bigint[];
  v_txt_ids    text[];
  v_hist_uuids uuid[];
BEGIN

  SELECT id_auto, role INTO v_id_auto, v_role
  FROM profiles WHERE id = v_uid;

  IF v_id_auto IS NULL THEN
    RAISE EXCEPTION 'Profile not found for user %', v_uid;
  END IF;

  -- ── Protected accounts: refuse, never cascade, never reassign ─────────────────────────
  -- Admin / house accounts and any account that owns or directs operational records must be
  -- transferred or removed by another administrator. Self-service deletion never deletes
  -- tournaments, templates, venues or giveaways, and never silently reassigns them.
  IF v_role IN ('compete_admin', 'super_admin') THEN
    RAISE EXCEPTION 'This account must be transferred or removed by another administrator.'
      USING ERRCODE = 'P0001', DETAIL = 'admin_account';
  END IF;

  IF EXISTS (SELECT 1 FROM tournaments WHERE director_id = v_id_auto)
     OR EXISTS (SELECT 1 FROM tournament_templates WHERE director_id = v_id_auto)
     OR EXISTS (SELECT 1 FROM venue_owners WHERE owner_id = v_id_auto AND archived_at IS NULL)
     OR EXISTS (SELECT 1 FROM giveaways WHERE created_by = v_id_auto OR winner_drawn_by = v_id_auto)
     OR EXISTS (SELECT 1 FROM giveaway_draws WHERE drawn_by = v_id_auto)
     OR EXISTS (SELECT 1 FROM giveaway_winner_history WHERE drawn_by = v_id_auto)
  THEN
    RAISE EXCEPTION 'This account must be transferred or removed by another administrator.'
      USING ERRCODE = 'P0001', DETAIL = 'owns_operational_records';
  END IF;

  DELETE FROM alert_matches WHERE alert_id IN (
    SELECT id FROM search_alerts WHERE user_id = v_id_auto
  );
  DELETE FROM search_alerts WHERE user_id = v_id_auto;
  DELETE FROM saved_searches WHERE user_id = v_id_auto;
  DELETE FROM favorites WHERE user_id = v_id_auto;
  DELETE FROM giveaway_winner_history WHERE user_id = v_id_auto;
  DELETE FROM giveaway_entries WHERE user_id = v_id_auto;
  DELETE FROM notifications WHERE user_id = v_id_auto;
  DELETE FROM notification_message_recipients WHERE user_id = v_uid;
  DELETE FROM notification_preferences WHERE user_id = v_uid;
  DELETE FROM push_tokens WHERE user_id = v_uid;
  SELECT coalesce(array_agg(id), ARRAY[]::int[]) INTO v_msg_ids
  FROM messages WHERE sender_id = v_id_auto;
  IF array_length(v_msg_ids, 1) > 0 THEN
    DELETE FROM message_recipients WHERE message_id = ANY(v_msg_ids);
    DELETE FROM messages WHERE id = ANY(v_msg_ids);
  END IF;
  DELETE FROM message_recipients WHERE user_id = v_id_auto;
  DELETE FROM message_rate_limits WHERE sender_id = v_uid;
  DELETE FROM conversation_messages WHERE sender_id = v_uid;
  DELETE FROM conversation_participants WHERE user_id = v_uid;
  DELETE FROM support_tickets WHERE user_id = v_id_auto;
  DELETE FROM tournament_templates_user WHERE user_id = v_id_auto;
  DELETE FROM featured_players WHERE user_id = v_id_auto;
  DELETE FROM audit_log WHERE user_id = v_id_auto;
  DELETE FROM venue_directors WHERE director_id = v_id_auto;
  DELETE FROM venue_owners WHERE owner_id = v_id_auto;

  -- Giveaway draws this user won (NOT NULL col). Draws they performed are guarded above.
  DELETE FROM giveaway_draws WHERE winner_id = v_id_auto;
  UPDATE giveaway_draws SET invalidated_by = NULL WHERE invalidated_by = v_id_auto;

  UPDATE giveaway_winner_history SET disqualified_by = NULL WHERE disqualified_by = v_id_auto;

  -- Giveaways where this user won (nullable)
  UPDATE giveaways SET winner_id = NULL WHERE winner_id = v_id_auto;

  -- Support tickets (nullable)
  UPDATE support_tickets SET resolved_by = NULL WHERE resolved_by = v_id_auto;
  UPDATE support_tickets SET assigned_to = NULL WHERE assigned_to = v_id_auto;

  UPDATE tournaments SET archived_by = NULL WHERE archived_by = v_id_auto;
  UPDATE tournaments SET cancelled_by = NULL WHERE cancelled_by = v_id_auto;

  UPDATE tournament_templates SET archived_by = NULL WHERE archived_by = v_id_auto;

  -- Venue references (nullable)
  UPDATE venue_directors SET assigned_by = NULL WHERE assigned_by = v_id_auto;
  UPDATE venue_directors SET archived_by = NULL WHERE archived_by = v_id_auto;
  UPDATE venue_owners SET assigned_by = NULL WHERE assigned_by = v_id_auto;
  UPDATE venue_owners SET archived_by = NULL WHERE archived_by = v_id_auto;
  UPDATE venues SET archived_by = NULL WHERE archived_by = v_id_auto;

  -- Conversations created by user (created_by is NOT NULL)
  SELECT coalesce(array_agg(id), ARRAY[]::uuid[]) INTO v_conv_ids
  FROM conversations WHERE created_by = v_uid;
  IF array_length(v_conv_ids, 1) > 0 THEN
    DELETE FROM conversation_messages WHERE conversation_id = ANY(v_conv_ids);
    DELETE FROM conversation_participants WHERE conversation_id = ANY(v_conv_ids);
    DELETE FROM conversations WHERE id = ANY(v_conv_ids);
  END IF;

  -- Notification messages sent by user (sender_id is NOT NULL)
  SELECT coalesce(array_agg(id), ARRAY[]::uuid[]) INTO v_nmsg_ids
  FROM notification_messages WHERE sender_id = v_uid;
  IF array_length(v_nmsg_ids, 1) > 0 THEN
    DELETE FROM notification_message_recipients WHERE message_id = ANY(v_nmsg_ids);
    DELETE FROM notification_messages WHERE id = ANY(v_nmsg_ids);
  END IF;

  -- NEW: records that used to block deletion ------------------------------------------
  UPDATE bar_requests SET submitted_by = NULL WHERE submitted_by = v_uid;   -- venue suggestion stays, unlinked
  UPDATE bar_requests SET reviewed_by = NULL WHERE reviewed_by = v_uid;
  DELETE FROM image_scan_logs WHERE user_id = v_uid;                        -- moderation logs of the user's uploads
  UPDATE venue_audits SET owner_id = NULL WHERE owner_id = v_id_auto;       -- venue data stays, unlinked
  UPDATE reassignment_logs SET previous_user_id = NULL, previous_user_name = 'Deleted user' WHERE previous_user_id = v_id_auto;
  UPDATE reassignment_logs SET new_user_id = NULL, new_user_name = 'Deleted user' WHERE new_user_id = v_id_auto;
  UPDATE reassignment_logs SET reassigned_by = NULL, reassigned_by_name = 'Deleted user' WHERE reassigned_by = v_id_auto;

  -- NEW: retained tournament history is kept but de-identified -------------------------
  SELECT coalesce(array_agg(id), ARRAY[]::uuid[]) INTO v_player_ids
  FROM players WHERE profile_id = v_uid;

  -- Unlink history rows from the profile while KEEPING their players link. The players-sync
  -- triggers re-derive the player uuid whenever the profile id changes (to NULL here), so
  -- each table is unlinked first and its original player uuid restored in a second update.
  -- (Previously the FK ON DELETE SET NULL did this implicitly and the trigger erased the
  -- player link, orphaning the deleted user's past results.)
  -- Registrations / team seats: the guarded sync triggers (§3) keep player_uuid when
  -- player_id is cleared.
  UPDATE tournament_players SET player_id = NULL WHERE player_id = v_id_auto;
  UPDATE tournament_team_members SET player_id = NULL WHERE player_id = v_id_auto;

  -- Chip rows: their sync triggers are left unchanged, so unlink then restore the uuid.

  SELECT coalesce(array_agg(id), ARRAY[]::text[]), coalesce(array_agg(p1_player_id), ARRAY[]::uuid[])
    INTO v_txt_ids, v_hist_uuids
    FROM chip_entries WHERE p1_profile_id = v_id_auto;
  IF array_length(v_txt_ids, 1) > 0 THEN
    UPDATE chip_entries SET p1_profile_id = NULL WHERE id = ANY(v_txt_ids);
    UPDATE chip_entries ce SET p1_player_id = u.pu
      FROM unnest(v_txt_ids, v_hist_uuids) AS u(id, pu) WHERE ce.id = u.id;
  END IF;
  SELECT coalesce(array_agg(id), ARRAY[]::text[]), coalesce(array_agg(p2_player_id), ARRAY[]::uuid[])
    INTO v_txt_ids, v_hist_uuids
    FROM chip_entries WHERE p2_profile_id = v_id_auto;
  IF array_length(v_txt_ids, 1) > 0 THEN
    UPDATE chip_entries SET p2_profile_id = NULL WHERE id = ANY(v_txt_ids);
    UPDATE chip_entries ce SET p2_player_id = u.pu
      FROM unnest(v_txt_ids, v_hist_uuids) AS u(id, pu) WHERE ce.id = u.id;
  END IF;
  -- The stored phone on the user's chip entries (p1 is the only phone column).
  UPDATE chip_entries SET p1_phone = NULL
   WHERE p1_phone IS NOT NULL AND p1_player_id = ANY(v_player_ids);

  SELECT coalesce(array_agg(id), ARRAY[]::bigint[]), coalesce(array_agg(p1_player_id), ARRAY[]::uuid[])
    INTO v_big_ids, v_hist_uuids
    FROM chip_results WHERE p1_profile_id = v_id_auto;
  IF array_length(v_big_ids, 1) > 0 THEN
    UPDATE chip_results SET p1_profile_id = NULL WHERE id = ANY(v_big_ids);
    UPDATE chip_results cr SET p1_player_id = u.pu
      FROM unnest(v_big_ids, v_hist_uuids) AS u(id, pu) WHERE cr.id = u.id;
  END IF;
  SELECT coalesce(array_agg(id), ARRAY[]::bigint[]), coalesce(array_agg(p2_player_id), ARRAY[]::uuid[])
    INTO v_big_ids, v_hist_uuids
    FROM chip_results WHERE p2_profile_id = v_id_auto;
  IF array_length(v_big_ids, 1) > 0 THEN
    UPDATE chip_results SET p2_profile_id = NULL WHERE id = ANY(v_big_ids);
    UPDATE chip_results cr SET p2_player_id = u.pu
      FROM unnest(v_big_ids, v_hist_uuids) AS u(id, pu) WHERE cr.id = u.id;
  END IF;

  -- Team captaincy moves to the retained player row (captain_id is ON DELETE CASCADE,
  -- which would otherwise delete the whole team, including the partner's history).
  -- The captain sync trigger keeps captain_player_id when captain_id is cleared (see §3).
  UPDATE tournament_teams
     SET captain_id = NULL,
         captain_player_id = coalesce(captain_player_id, v_player_ids[1])
   WHERE captain_id = v_id_auto
     AND coalesce(captain_player_id, v_player_ids[1]) IS NOT NULL;

  IF array_length(v_player_ids, 1) > 0 THEN
    DELETE FROM player_invitations WHERE player_id = ANY(v_player_ids);
    UPDATE players
       SET email = NULL,            -- email_normalized is generated from email
           phone_e164 = NULL,
           profile_id = NULL,
           account_status = 'DISABLED',
           updated_at = now()
     WHERE id = ANY(v_player_ids);
  END IF;

  DELETE FROM profiles WHERE id = v_uid;
  DELETE FROM auth.users WHERE id = v_uid;

END;
$function$
;

CREATE OR REPLACE FUNCTION public.chip_apply(p_tid bigint, p_expected_version bigint, p_config jsonb, p_entries jsonb, p_matches jsonb, p_tables jsonb, p_events jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_cur   bigint;
  v_next  bigint;
  v_actor bigint;
begin
  if not public.can_manage_tournament(p_tid) then
    raise exception 'not authorized to manage tournament %', p_tid using errcode = '42501';
  end if;

  select id_auto into v_actor from public.profiles where id = auth.uid();

  -- Lock + CAS. Reject stale writes cleanly, before any mutation.
  select version into v_cur from public.chip_config where tournament_id = p_tid for update;
  v_cur := coalesce(v_cur, 0);
  if p_expected_version is not null and v_cur is distinct from p_expected_version then
    return jsonb_build_object('ok', false, 'conflict', true, 'version', v_cur);
  end if;
  v_next := v_cur + 1;

  -- Config: engine-owned fields + version bump. On an existing row the settings columns
  -- (format/tiers/performance_tracking/…) are NOT listed, so they are preserved.
  insert into public.chip_config as cc (
    tournament_id, format, queue, started_at, finished_at, winner_entry_id,
    reshuffle_count, reshuffle_pending, reshuffle_table_count,
    shuffle_mode, shuffle_ready, shuffle_round, round_remaining, restore_points,
    reshuffle_removing_ids, version, updated_at
  ) values (
    p_tid,
    coalesce(p_config->>'format', 'singles'),
    coalesce(p_config->'queue', '[]'::jsonb),
    (p_config->>'started_at')::timestamptz,
    (p_config->>'finished_at')::timestamptz,
    p_config->>'winner_entry_id',
    coalesce((p_config->>'reshuffle_count')::int, 0),
    coalesce((p_config->>'reshuffle_pending')::boolean, false),
    (p_config->>'reshuffle_table_count')::int,
    coalesce((p_config->>'shuffle_mode')::boolean, false),
    coalesce((p_config->>'shuffle_ready')::boolean, false),
    coalesce((p_config->>'shuffle_round')::boolean, false),
    coalesce(p_config->'round_remaining', '[]'::jsonb),
    coalesce(p_config->'restore_points', '[]'::jsonb),
    coalesce(p_config->'reshuffle_removing_ids', '[]'::jsonb),
    v_next, now()
  )
  on conflict (tournament_id) do update set
    queue                  = excluded.queue,
    started_at             = excluded.started_at,
    finished_at            = excluded.finished_at,
    winner_entry_id        = excluded.winner_entry_id,
    reshuffle_count        = excluded.reshuffle_count,
    reshuffle_pending      = excluded.reshuffle_pending,
    reshuffle_table_count  = excluded.reshuffle_table_count,
    shuffle_mode           = excluded.shuffle_mode,
    shuffle_ready          = excluded.shuffle_ready,
    shuffle_round          = excluded.shuffle_round,
    round_remaining        = excluded.round_remaining,
    restore_points         = excluded.restore_points,
    reshuffle_removing_ids = excluded.reshuffle_removing_ids,
    version                = v_next,
    updated_at             = now();

  -- Engine rows: replace the owned set atomically (safe under CAS).
  delete from public.chip_entries where tournament_id = p_tid;
  if jsonb_typeof(p_entries) = 'array' then
    insert into public.chip_entries
      select * from jsonb_populate_recordset(null::public.chip_entries, p_entries);
  end if;

  delete from public.chip_matches where tournament_id = p_tid;
  if jsonb_typeof(p_matches) = 'array' then
    insert into public.chip_matches
      select * from jsonb_populate_recordset(null::public.chip_matches, p_matches);
  end if;

  delete from public.chip_tables where tournament_id = p_tid;
  if jsonb_typeof(p_tables) = 'array' then
    insert into public.chip_tables
      select * from jsonb_populate_recordset(null::public.chip_tables, p_tables);
  end if;

  -- Events: append-only; actor_id stamped from the trusted server actor (item 22).
  if jsonb_typeof(p_events) = 'array' then
    insert into public.chip_events (id, tournament_id, type, text, actor_id, payload, tx_id, superseded, created_at)
      select x.id, x.tournament_id, x.type, x.text, v_actor, x.payload, x.tx_id, x.superseded, x.created_at
      from jsonb_populate_recordset(null::public.chip_events, p_events) x
      on conflict (id) do nothing;
  end if;

  return jsonb_build_object('ok', true, 'conflict', false, 'version', v_next);
end;
$function$
;

