CREATE OR REPLACE FUNCTION public.update_pending_player(p_tournament_id bigint, p_player_id uuid, p_first_name text, p_last_name text, p_email text, p_phone text DEFAULT NULL::text)
 RETURNS TABLE(player_id uuid, outcome text, account_status text, display_name text, email_masked text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_first text := btrim(coalesce(p_first_name, ''));
  v_last  text := btrim(coalesce(p_last_name, ''));
  v_email text := btrim(coalesce(p_email, ''));
  v_norm  text := lower(btrim(coalesce(p_email, '')));
  v_phone text := nullif(btrim(coalesce(p_phone, '')), '');
  v_cur   public.players%rowtype;
  v_other public.players%rowtype;
  v_actor_ida  bigint;
  v_actor_role text;
  v_changed    text[] := '{}';
begin
  if not public.can_manage_tournament(p_tournament_id) then
    raise exception 'Not authorized to edit players for this tournament';
  end if;
  if v_first = '' or v_last = '' then
    raise exception 'First and last name are required';
  end if;
  if v_email = '' or v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
    raise exception 'A valid email is required';
  end if;

  select * into v_cur from public.players where id = p_player_id for update;
  if not found then
    raise exception 'Player not found for this tournament';
  end if;

  if not exists (
        select 1 from public.tournament_players tp
        where tp.tournament_id = p_tournament_id and tp.player_uuid = p_player_id and tp.status <> 'cancelled'
      )
     and not exists (
        select 1 from public.tournament_team_members m
        where m.tournament_id = p_tournament_id and m.player_uuid = p_player_id and m.invite_status <> 'declined'
      ) then
    raise exception 'Player not found for this tournament';
  end if;

  if v_cur.account_status <> 'PENDING' or v_cur.profile_id is not null then
    raise exception 'This player has been claimed and can no longer be edited'
      using errcode = 'check_violation';
  end if;

  select * into v_other from public.players
   where email_normalized = v_norm and id <> p_player_id;
  if found then
    if v_other.account_status = 'ACTIVE' then
      return query select v_other.id, 'EMAIL_BELONGS_TO_ACTIVE_PLAYER'::text,
        v_other.account_status, v_other.display_name, public.mask_email(v_other.email);
      return;
    elsif v_other.account_status = 'PENDING' then
      return query select v_other.id, 'EMAIL_BELONGS_TO_PENDING_PLAYER'::text,
        v_other.account_status, v_other.display_name, public.mask_email(v_other.email);
      return;
    else
      raise exception 'An account with this email is disabled; contact an admin'
        using errcode = 'check_violation';
    end if;
  end if;

  if btrim(coalesce(v_cur.first_name, '')) <> v_first then v_changed := array_append(v_changed, 'first_name'); end if;
  if btrim(coalesce(v_cur.last_name, ''))  <> v_last  then v_changed := array_append(v_changed, 'last_name');  end if;
  if lower(btrim(coalesce(v_cur.email, ''))) <> v_norm then v_changed := array_append(v_changed, 'email');      end if;
  if coalesce(v_cur.phone_e164, '') <> coalesce(v_phone, '') then v_changed := array_append(v_changed, 'phone'); end if;

  update public.players
     set first_name   = v_first,
         last_name    = v_last,
         display_name = v_first || ' ' || v_last,
         email        = v_email,
         phone_e164   = v_phone,
         updated_at   = now()
   where id = p_player_id;

  if 'email' = any (v_changed) then
    update public.player_invitations
       set superseded_at = now()
     where public.player_invitations.player_id = p_player_id
       and accepted_at is null and superseded_at is null and revoked_at is null;
  end if;

  select id_auto, role into v_actor_ida, v_actor_role from public.profiles where id = auth.uid();
  insert into public.audit_log (user_id, user_role, action, entity_type, entity_id, details)
  values (
    v_actor_ida, v_actor_role, 'update_pending_player', 'player', null,
    jsonb_build_object(
      'player_id',        p_player_id,
      'tournament_id',    p_tournament_id,
      'changed',          v_changed,
      'old_email_masked', public.mask_email(v_cur.email),
      'new_email_masked', public.mask_email(v_email)
    )
  );

  return query select p_player_id, 'UPDATED'::text, 'PENDING'::text,
                      v_first || ' ' || v_last, public.mask_email(v_email);

exception when unique_violation then
  select * into v_other from public.players where email_normalized = v_norm and id <> p_player_id;
  if found then
    return query select v_other.id,
      case when v_other.account_status = 'ACTIVE'
           then 'EMAIL_BELONGS_TO_ACTIVE_PLAYER' else 'EMAIL_BELONGS_TO_PENDING_PLAYER' end,
      v_other.account_status, v_other.display_name, public.mask_email(v_other.email);
    return;
  end if;
  raise;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.submit_content_report(p_content_type text, p_content_id text, p_reason text, p_details text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid      uuid := auth.uid();
  v_id       uuid;
  v_target   uuid;
  v_reported uuid;
  v_snap     jsonb;
  v_prof     record;
  v_msg      record;
  v_rev      record;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;
  if p_content_type is null or p_content_type <> all (array['user','message','review']) then
    raise exception 'unsupported_content_type' using errcode = '22023';
  end if;
  if p_reason is null or p_reason <> all (array['inappropriate','spam','misleading','harassment','other']) then
    raise exception 'invalid_reason' using errcode = '22023';
  end if;
  if p_content_id is null or p_content_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    raise exception 'not_found' using errcode = 'P0002';
  end if;
  v_target := p_content_id::uuid;

  -- One report per reporter per item (idempotent: return the existing report).
  select id into v_id from public.reports
   where reporter_id = v_uid and content_type = p_content_type and content_id = p_content_id
   limit 1;
  if v_id is not null then
    return v_id;
  end if;

  if p_content_type = 'user' then
    select id, user_name, name, role into v_prof from public.profiles where id = v_target;
    if v_prof.id is null then raise exception 'not_found' using errcode = 'P0002'; end if;
    if v_prof.id = v_uid then raise exception 'cannot_report_self' using errcode = '22023'; end if;
    v_reported := v_prof.id;
    v_snap := jsonb_build_object('user_name', v_prof.user_name, 'name', v_prof.name, 'role', v_prof.role);

  elsif p_content_type = 'message' then
    select m.id, m.body, m.sender_id, m.conversation_id, m.created_at,
           c.is_support, c.category, p.user_name as sender_user_name, p.name as sender_name
      into v_msg
      from public.conversation_messages m
      join public.conversations c on c.id = m.conversation_id
      left join public.profiles p on p.id = m.sender_id
     where m.id = v_target;
    -- Only a participant of the conversation can report one of its messages.
    if v_msg.id is null or not exists (
         select 1 from public.conversation_participants cp
          where cp.conversation_id = v_msg.conversation_id and cp.user_id = v_uid) then
      raise exception 'not_found' using errcode = 'P0002';
    end if;
    if v_msg.sender_id = v_uid then raise exception 'cannot_report_self' using errcode = '22023'; end if;
    v_reported := v_msg.sender_id;
    v_snap := jsonb_build_object(
      'body', left(v_msg.body, 2000), 'sent_at', v_msg.created_at,
      'conversation_id', v_msg.conversation_id, 'category', v_msg.category, 'is_support', v_msg.is_support,
      'sender_user_name', v_msg.sender_user_name, 'sender_name', v_msg.sender_name);

  else -- review
    select r.id, r.reviewer_id, r.tournament_id, r.tournament_name, r.rating, r.comment,
           r.selected_reasons, r.submitted_at
      into v_rev
      from public.tournament_reviews r
     where r.id = v_target;
    -- Only someone who can see the review (its TD / venue owner / admin) can report it.
    if v_rev.id is null or not public.can_view_tournament_reviews(v_rev.tournament_id) then
      raise exception 'not_found' using errcode = 'P0002';
    end if;
    if v_rev.reviewer_id = v_uid then raise exception 'cannot_report_self' using errcode = '22023'; end if;
    v_reported := v_rev.reviewer_id;
    v_snap := jsonb_build_object(
      'rating', v_rev.rating, 'comment', left(v_rev.comment, 2000), 'reasons', to_jsonb(v_rev.selected_reasons),
      'tournament_id', v_rev.tournament_id, 'tournament_name', v_rev.tournament_name, 'submitted_at', v_rev.submitted_at);
  end if;

  insert into public.reports (reporter_id, content_type, content_id, reason, details, reported_user_id, content_snapshot)
  values (v_uid, p_content_type, p_content_id, p_reason, nullif(left(btrim(coalesce(p_details, '')), 1000), ''),
          -- reported_user_id must reference a live profile (FK); snapshot keeps the context either way
          (select id from public.profiles where id = v_reported), v_snap)
  returning id into v_id;

  return v_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.block_message_if_users_blocked()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  -- Support conversations are exempt: users can always reach Compete staff.
  if exists (select 1 from public.conversations c where c.id = new.conversation_id and c.is_support) then
    return new;
  end if;
  if exists (
    select 1
      from public.conversation_participants cp
      join public.user_blocks b
        on (b.blocker_id = new.sender_id and b.blocked_id = cp.user_id)
        or (b.blocker_id = cp.user_id and b.blocked_id = new.sender_id)
     where cp.conversation_id = new.conversation_id
       and cp.user_id <> new.sender_id
  ) then
    raise exception 'blocked' using errcode = 'P0001';
  end if;
  return new;
end;
$function$
;

