CREATE OR REPLACE FUNCTION public._elim_resolve(p_ls jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_graph jsonb := coalesce(p_ls #> '{bracket,graph}', '[]'::jsonb);
  v_seeds jsonb := coalesce(p_ls #> '{bracket,seeds}', '[]'::jsonb);
  v_ms    jsonb := case when jsonb_typeof(p_ls -> 'matchState') = 'object'
                        then p_ls -> 'matchState' else '{}'::jsonb end;
  v_ids   text[];
  v_out   jsonb := '{}'::jsonb;   -- id -> {wd,wr,ld,lr}  (winner/loser decided + reg)
  v_res   jsonb := '{}'::jsonb;   -- id -> {p1,p2,real}
  v_node  jsonb;
  v_id    text;
  v_pass  int := 0;
  v_prog  boolean;
  v_ready boolean;
  -- per slot
  v_ref   jsonb;
  v_k     int;
  v_st    text[];
  v_reg   bigint[];
  v_src   text;
  v_so    jsonb;
  v_seed  jsonb;
  -- per node
  v_skipped boolean; v_pending boolean; v_empty boolean; v_bye boolean;
  v_present int; v_r jsonb; v_rc boolean; v_rw int; v_rres text;
  v_wd boolean; v_wr bigint; v_ld boolean; v_lr bigint; v_bye_reg bigint;
begin
  if jsonb_typeof(v_graph) <> 'array' then return '{}'::jsonb; end if;
  select coalesce(array_agg(n ->> 'id'), '{}') into v_ids from jsonb_array_elements(v_graph) n;

  loop
    v_pass := v_pass + 1;
    v_prog := false;
    for v_node in select value from jsonb_array_elements(v_graph) loop
      v_id := v_node ->> 'id';
      if v_id is null or v_out ? v_id then continue; end if;

      v_ready := true;
      v_st := array[null, null]::text[];
      v_reg := array[null, null]::bigint[];
      for v_k in 1..2 loop
        v_ref := v_node -> ('slot' || v_k);
        if v_ref ->> 'kind' = 'seed' then
          v_seed := v_seeds -> ((v_ref ->> 'seedIndex')::int);
          if jsonb_typeof(v_seed) = 'object' and (v_seed ->> 'registrationId') is not null then
            v_st[v_k] := 'player'; v_reg[v_k] := (v_seed ->> 'registrationId')::bigint;
          else
            v_st[v_k] := 'empty';
          end if;
        elsif v_ref ->> 'kind' in ('winner', 'loser') then
          v_src := v_ref ->> 'matchId';
          if v_src is null or not (v_src = any(v_ids)) then
            v_st[v_k] := 'empty';                         -- unknown feeder → nobody arrives
          elsif not (v_out ? v_src) then
            v_ready := false;                             -- feeder not resolved yet this pass
          else
            v_so := v_out -> v_src;
            if v_ref ->> 'kind' = 'winner' then
              if not (v_so ->> 'wd')::boolean then v_st[v_k] := 'pending';
              elsif v_so ->> 'wr' is null then v_st[v_k] := 'empty';
              else v_st[v_k] := 'player'; v_reg[v_k] := (v_so ->> 'wr')::bigint; end if;
            else
              if not (v_so ->> 'ld')::boolean then v_st[v_k] := 'pending';
              elsif v_so ->> 'lr' is null then v_st[v_k] := 'empty';
              else v_st[v_k] := 'player'; v_reg[v_k] := (v_so ->> 'lr')::bigint; end if;
            end if;
          end if;
        else
          v_st[v_k] := 'empty';                           -- {kind:"empty"} or malformed
        end if;
      end loop;
      if not v_ready then continue; end if;

      v_skipped := coalesce(
                     coalesce((v_node ->> 'conditional')::boolean, false) and v_id = 'GF2'
                     and (v_ms #>> '{GF,status}') = 'completed'
                     and (v_ms #>> '{GF,winner}') = '1',
                   false);
      v_present := (case when v_st[1] = 'player' then 1 else 0 end)
                 + (case when v_st[2] = 'player' then 1 else 0 end);
      v_pending := not v_skipped and (v_st[1] = 'pending' or v_st[2] = 'pending');
      v_empty   := not v_skipped and not v_pending and v_present = 0;
      v_bye     := not v_skipped and not v_pending and v_present = 1;
      v_bye_reg := case when v_st[1] = 'player' then v_reg[1] else v_reg[2] end;

      v_r    := v_ms -> v_id;
      v_rc   := coalesce((v_r ->> 'status') = 'completed', false);
      v_rw   := case when (v_r ->> 'winner') in ('1', '2') then (v_r ->> 'winner')::int end;
      v_rres := v_r ->> 'result';

      -- winner flow
      if v_skipped or v_empty then v_wd := true; v_wr := null;
      elsif v_bye then
        v_wd := true;
        v_wr := case when v_rc and v_rres in ('forfeit', 'withdraw') then null else v_bye_reg end;
      elsif v_pending then v_wd := false; v_wr := null;
      elsif v_rc and v_rw is not null then v_wd := true; v_wr := v_reg[v_rw];
      else v_wd := false; v_wr := null;
      end if;
      -- loser flow
      if v_skipped or v_empty or v_bye then v_ld := true; v_lr := null;
      elsif v_pending then v_ld := false; v_lr := null;
      elsif v_rc and v_rw is not null then
        v_ld := true;
        v_lr := case when v_rres = 'withdraw' then null else v_reg[3 - v_rw] end;
      else v_ld := false; v_lr := null;
      end if;

      v_out := v_out || jsonb_build_object(v_id,
        jsonb_build_object('wd', v_wd, 'wr', v_wr, 'ld', v_ld, 'lr', v_lr));
      v_res := v_res || jsonb_build_object(v_id, jsonb_build_object(
        'p1', v_reg[1], 'p2', v_reg[2],
        'real', not v_skipped and not v_pending and v_present = 2));
      v_prog := true;
    end loop;
    exit when not v_prog or v_pass > 300;
  end loop;
  return v_res;
end;
$function$
;

CREATE OR REPLACE FUNCTION public._elim_apply_one(p_tournament_id bigint, p_ids text[], p_ms jsonb, p_op jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_kind   text := p_op ->> 'op';
  v_mid    text;
  v_cur    jsonb;
  v_status text;
  v_new    jsonb;
  v_set    jsonb;
  v_key    text;
  v_val    jsonb;
  v_tid    bigint;
  v_start  boolean;
  v_top    jsonb := '{}'::jsonb;
  v_now    text := to_char(now() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
  v_nstat  text;
  v_started boolean := false;
  v_tstat  text;
  v_allowed constant text[] := array['status', 'winner', 'p1Score', 'p2Score', 'startedAt',
                                     'completedAt', 'result', 'timerSeconds', 'tableId',
                                     'preferredTableId'];
begin
  if jsonb_typeof(p_op) <> 'object' or v_kind is null then
    raise exception 'invalid_op' using errcode = 'P0001';
  end if;

  -- ── set_queue: only queueOrder / autoAssignMode / autoAssignEnabled / queuePins ─────
  if v_kind = 'set_queue' then
    if p_op ? 'queueOrder' then
      if jsonb_typeof(p_op -> 'queueOrder') <> 'array'
         or jsonb_array_length(p_op -> 'queueOrder') > 512 then
        raise exception 'invalid_queue_order' using errcode = 'P0001';
      end if;
      if exists (
        select 1 from jsonb_array_elements(p_op -> 'queueOrder') e
        where jsonb_typeof(e) <> 'string' or not ((e #>> '{}') = any(p_ids))
      ) then
        raise exception 'unknown_match' using errcode = 'P0001';
      end if;
      v_top := v_top || jsonb_build_object('queueOrder', p_op -> 'queueOrder');
    end if;
    if p_op ? 'autoAssignMode' then
      if jsonb_typeof(p_op -> 'autoAssignMode') <> 'string'
         or (p_op ->> 'autoAssignMode') not in
            ('balanced', 'winnersFirst', 'losersFirst', 'longestWait', 'manual') then
        raise exception 'invalid_mode' using errcode = 'P0001';
      end if;
      v_top := v_top || jsonb_build_object('autoAssignMode', p_op -> 'autoAssignMode');
    end if;
    if p_op ? 'autoAssignEnabled' then
      if jsonb_typeof(p_op -> 'autoAssignEnabled') <> 'boolean' then
        raise exception 'invalid_value' using errcode = 'P0001';
      end if;
      v_top := v_top || jsonb_build_object('autoAssignEnabled', p_op -> 'autoAssignEnabled');
    end if;
    if p_op ? 'queuePins' then
      -- Shape only (the client resolves pins against the live schedule deterministically and
      -- ignores any that became stale): an array of ≤ 32 objects with exactly the allowed keys,
      -- ids from this bracket, a legal place, an anchor for before/after (≠ itself) and none for
      -- top/bottom, and at most one pin per match.
      if jsonb_typeof(p_op -> 'queuePins') <> 'array'
         or jsonb_array_length(p_op -> 'queuePins') > 32 then
        raise exception 'invalid_queue_pins' using errcode = 'P0001';
      end if;
      if exists (
        select 1 from jsonb_array_elements(p_op -> 'queuePins') e
        where jsonb_typeof(e) <> 'object'
           or exists (select 1 from jsonb_object_keys(e) k where k not in ('matchId', 'place', 'anchorId'))
           or coalesce(jsonb_typeof(e -> 'matchId'), '') <> 'string'
           or not coalesce((e ->> 'matchId') = any(p_ids), false)
           or coalesce(e ->> 'place', '') not in ('before', 'after', 'top', 'bottom')
           or ((e ->> 'place') in ('before', 'after') and (
                 coalesce(jsonb_typeof(e -> 'anchorId'), '') <> 'string'
                 or not coalesce((e ->> 'anchorId') = any(p_ids), false)
                 or (e ->> 'anchorId') = (e ->> 'matchId')))
           or ((e ->> 'place') in ('top', 'bottom') and e ? 'anchorId')
      ) or (
        select count(distinct e ->> 'matchId') from jsonb_array_elements(p_op -> 'queuePins') e
      ) <> jsonb_array_length(p_op -> 'queuePins') then
        raise exception 'invalid_queue_pins' using errcode = 'P0001';
      end if;
      v_top := v_top || jsonb_build_object('queuePins', p_op -> 'queuePins');
    end if;
    if v_top = '{}'::jsonb then
      raise exception 'empty_op' using errcode = 'P0001';
    end if;
    return jsonb_build_object('ms', p_ms, 'top', v_top, 'started', false);
  end if;

  -- ── match ops: matchId must be a node of this bracket ────────────────────────────────
  if v_kind not in ('assign', 'start', 'unassign', 'patch_match') then
    raise exception 'invalid_op' using errcode = 'P0001';
  end if;
  v_mid := p_op ->> 'matchId';
  if v_mid is null or jsonb_typeof(p_op -> 'matchId') <> 'string' or not (v_mid = any(p_ids)) then
    raise exception 'unknown_match' using errcode = 'P0001';
  end if;
  v_cur := case when jsonb_typeof(p_ms -> v_mid) = 'object' then p_ms -> v_mid else '{}'::jsonb end;
  v_status := coalesce(v_cur ->> 'status', 'scheduled');

  if v_kind = 'assign' then
    if v_status in ('in_progress', 'completed') then
      raise exception 'match_%', v_status using errcode = 'P0001';
    end if;
    if jsonb_typeof(p_op -> 'tableId') <> 'number' or (p_op ->> 'tableId') !~ '^[0-9]{1,18}$' then
      raise exception 'invalid_table' using errcode = 'P0001';
    end if;
    v_tid := (p_op ->> 'tableId')::bigint;
    if (p_op ? 'start' and jsonb_typeof(p_op -> 'start') <> 'boolean')
       or (p_op ? 'ifUnassigned' and jsonb_typeof(p_op -> 'ifUnassigned') <> 'boolean') then
      raise exception 'invalid_value' using errcode = 'P0001';
    end if;
    -- Auto Assign: never move a match that already has a table (another device got there).
    if coalesce((p_op ->> 'ifUnassigned')::boolean, false)
       and jsonb_typeof(v_cur -> 'tableId') = 'number' then
      raise exception 'match_assigned' using errcode = 'P0001';
    end if;
    v_start := coalesce((p_op ->> 'start')::boolean, false);
    perform public._elim_check_table(p_tournament_id, p_ms, v_mid, v_tid);
    v_new := (v_cur - 'preferredTableId' - 'clearedAt') || jsonb_build_object(
      'tableId', v_tid,
      'status', case when v_start then 'in_progress' else 'scheduled' end,
      'startedAt', case when v_start then to_jsonb(v_now) else 'null'::jsonb end,
      -- a new assignment (or a table change) gets a new assignedAt; re-assigning the same
      -- table keeps the original, so it is not a new notification event
      'assignedAt', case when (v_cur ->> 'tableId') = v_tid::text and jsonb_typeof(v_cur -> 'assignedAt') = 'string'
                         then v_cur -> 'assignedAt' else to_jsonb(v_now) end);
    v_started := v_start;

  elsif v_kind = 'start' then
    if v_status <> 'scheduled' then
      raise exception 'match_%', v_status using errcode = 'P0001';
    end if;
    if jsonb_typeof(v_cur -> 'tableId') is distinct from 'number' then
      raise exception 'no_table' using errcode = 'P0001';
    end if;
    v_new := v_cur || jsonb_build_object('status', 'in_progress', 'startedAt', v_now);
    v_started := true;

  elsif v_kind = 'unassign' then
    if v_status = 'completed' then
      raise exception 'match_completed' using errcode = 'P0001';
    end if;
    -- "Clear Table": the match goes back to the Ready queue and is stamped so server-side Auto
    -- Assign leaves it alone briefly (src/utils/clear-table.ts) instead of instantly re-taking it.
    v_new := v_cur || jsonb_build_object('tableId', null, 'status', 'scheduled', 'startedAt', null,
                                         'assignedAt', null, 'clearedAt', v_now);

  elsif v_kind = 'patch_match' then
    v_set := p_op -> 'set';
    if jsonb_typeof(v_set) <> 'object' or v_set = '{}'::jsonb then
      raise exception 'invalid_op' using errcode = 'P0001';
    end if;
    for v_key, v_val in select key, value from jsonb_each(v_set) loop
      if not (v_key = any(v_allowed)) then
        raise exception 'invalid_field' using errcode = 'P0001';
      end if;
      if v_key = 'status' then
        if jsonb_typeof(v_val) <> 'string'
           or (v_val #>> '{}') not in ('scheduled', 'in_progress', 'completed') then
          raise exception 'invalid_value' using errcode = 'P0001';
        end if;
      elsif v_key = 'winner' then
        if not (jsonb_typeof(v_val) = 'null' or v_val in ('1'::jsonb, '2'::jsonb)) then
          raise exception 'invalid_value' using errcode = 'P0001';
        end if;
      elsif v_key in ('p1Score', 'p2Score', 'timerSeconds') then
        if jsonb_typeof(v_val) <> 'null' and not (
             jsonb_typeof(v_val) = 'number'
             and (v_val #>> '{}') ~ '^[0-9]+$'
             and (v_val #>> '{}')::numeric <= case when v_key = 'timerSeconds' then 86400 else 999 end
           ) then
          raise exception 'invalid_value' using errcode = 'P0001';
        end if;
      elsif v_key in ('startedAt', 'completedAt') then
        if jsonb_typeof(v_val) <> 'null' then
          if jsonb_typeof(v_val) <> 'string' then
            raise exception 'invalid_value' using errcode = 'P0001';
          end if;
          begin
            perform (v_val #>> '{}')::timestamptz;
          exception when others then
            raise exception 'invalid_value' using errcode = 'P0001';
          end;
        end if;
      elsif v_key = 'result' then
        if not (jsonb_typeof(v_val) = 'null' or (jsonb_typeof(v_val) = 'string'
                and (v_val #>> '{}') in ('normal', 'forfeit', 'withdraw'))) then
          raise exception 'invalid_value' using errcode = 'P0001';
        end if;
      elsif v_key = 'tableId' then
        if jsonb_typeof(v_val) = 'number' and (v_val #>> '{}') ~ '^[0-9]{1,18}$' then
          perform public._elim_check_table(p_tournament_id, p_ms, v_mid, (v_val #>> '{}')::bigint);
        elsif jsonb_typeof(v_val) <> 'null' then
          raise exception 'invalid_table' using errcode = 'P0001';
        end if;
      elsif v_key = 'preferredTableId' then
        -- Play Next: a SOFT preference for a table (usually one that is busy right now). It
        -- must be one of this tournament's tables and not marked unavailable; it does NOT
        -- occupy the table (no occupancy check) and is only meaningful while the match has
        -- no table yet.
        if jsonb_typeof(v_val) = 'number' and (v_val #>> '{}') ~ '^[0-9]{1,18}$' then
          select tt.status into v_tstat
          from public.tournament_tables tt
          where tt.id = (v_val #>> '{}')::bigint and tt.tournament_id = p_tournament_id;
          if not found then
            raise exception 'table_not_found' using errcode = 'P0001';
          end if;
          if v_tstat = 'unavailable' then
            raise exception 'table_unavailable' using errcode = 'P0001';
          end if;
        elsif jsonb_typeof(v_val) <> 'null' then
          raise exception 'invalid_table' using errcode = 'P0001';
        end if;
      end if;
    end loop;

    v_new := v_cur || v_set;
    v_nstat := coalesce(v_new ->> 'status', 'scheduled');
    v_new := v_new || jsonb_build_object('status', v_nstat);  -- same default as setMatchState
    -- A completed match with no winner is only legal as a forfeit/withdrawal (nobody advances).
    if v_nstat = 'completed' and jsonb_typeof(v_new -> 'winner') is distinct from 'number'
       and coalesce(v_new ->> 'result', '') not in ('forfeit', 'withdraw') then
      raise exception 'invalid_transition' using errcode = 'P0001';
    end if;
    -- Play Next only while the match has no table.
    if jsonb_typeof(v_set -> 'preferredTableId') = 'number'
       and jsonb_typeof(v_new -> 'tableId') = 'number' then
      raise exception 'match_assigned' using errcode = 'P0001';
    end if;
    -- A genuine FIRST start (not a reopen/correction of a match that already has a start
    -- time) is stamped with server time, never the TD device clock.
    if v_nstat = 'in_progress' and v_status <> 'in_progress'
       and jsonb_typeof(v_cur -> 'startedAt') is distinct from 'string' then
      v_new := v_new || jsonb_build_object('startedAt', v_now);
    end if;
    -- assignedAt is server-owned: stamped when the table changes, cleared when removed.
    if v_set ? 'tableId' then
      if jsonb_typeof(v_new -> 'tableId') = 'number' then
        if (v_cur ->> 'tableId') is distinct from (v_new ->> 'tableId') then
          v_new := (v_new - 'preferredTableId') || jsonb_build_object('assignedAt', v_now);
        end if;
        v_new := v_new - 'clearedAt';
      else
        v_new := v_new || jsonb_build_object('assignedAt', null);
        -- a patch that TAKES the table away (Reset Match) gets the same brief Auto Assign hold
        if jsonb_typeof(v_cur -> 'tableId') = 'number' then
          v_new := v_new || jsonb_build_object('clearedAt', v_now);
        end if;
      end if;
    end if;
    if v_nstat = 'completed' then
      v_new := v_new - 'preferredTableId';
    end if;
    v_started := v_nstat = 'in_progress' and v_status <> 'in_progress';

  else
    raise exception 'invalid_op' using errcode = 'P0001';
  end if;

  return jsonb_build_object(
    'ms', p_ms || jsonb_build_object(v_mid, v_new),
    'top', '{}'::jsonb,
    'started', v_started);
end;
$function$
;

CREATE OR REPLACE FUNCTION public._elim_check_table(p_tournament_id bigint, p_ms jsonb, p_match_id text, p_table_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_status text;
begin
  select tt.status into v_status
  from public.tournament_tables tt
  where tt.id = p_table_id and tt.tournament_id = p_tournament_id;
  if not found then
    raise exception 'table_not_found' using errcode = 'P0001';
  end if;
  if v_status = 'unavailable' then
    raise exception 'table_unavailable' using errcode = 'P0001';
  end if;
  if exists (
    select 1 from jsonb_each(p_ms) e
    where e.key <> p_match_id
      and jsonb_typeof(e.value) = 'object'
      and (e.value ->> 'tableId') = p_table_id::text
      and coalesce(e.value ->> 'status', 'scheduled') <> 'completed'
  ) then
    raise exception 'table_occupied' using errcode = 'P0001';
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.elim_live_apply(p_tournament_id bigint, p_ops jsonb, p_atomic boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_row     record;
  v_ls      jsonb;
  v_ms      jsonb;
  v_ids     text[];
  v_op      jsonb;
  v_step    jsonb;
  v_results jsonb := '[]'::jsonb;
  v_i       int := 0;
  v_ok      int := 0;
  v_started boolean := false;
  v_state   text;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;
  if p_tournament_id is null or not public.can_manage_tournament(p_tournament_id) then
    raise exception 'Not allowed to manage this tournament' using errcode = '42501';
  end if;
  if p_ops is null or jsonb_typeof(p_ops) <> 'array'
     or jsonb_array_length(p_ops) < 1 or jsonb_array_length(p_ops) > 64 then
    raise exception 'ops must be an array of 1..64 operations' using errcode = '22023';
  end if;

  select t.live_settings, t.live_state, t.status, t.tournament_format
  into v_row
  from public.tournaments t
  where t.id = p_tournament_id
  for update;
  if not found then
    raise exception 'Tournament not found' using errcode = 'P0002';
  end if;
  if v_row.tournament_format = 'chip-tournament' then
    raise exception 'Not an elimination tournament' using errcode = '22023';
  end if;
  v_ls := coalesce(v_row.live_settings, '{}'::jsonb);
  if jsonb_typeof(v_ls #> '{bracket,graph}') is distinct from 'array' then
    raise exception 'No elimination bracket' using errcode = '22023';
  end if;
  select coalesce(array_agg(n ->> 'id'), '{}') into v_ids
  from jsonb_array_elements(v_ls #> '{bracket,graph}') n;
  v_ms := case when jsonb_typeof(v_ls -> 'matchState') = 'object'
               then v_ls -> 'matchState' else '{}'::jsonb end;

  for v_op in select value from jsonb_array_elements(p_ops) loop
    begin
      v_step := public._elim_apply_one(p_tournament_id, v_ids, v_ms, v_op);
      -- Adopt the result only on success: a failed op never partially mutates anything.
      v_ms := v_step -> 'ms';
      v_ls := v_ls || (v_step -> 'top');
      v_started := v_started or coalesce((v_step ->> 'started')::boolean, false);
      v_ok := v_ok + 1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('i', v_i, 'ok', true));
    exception when sqlstate 'P0001' then
      if p_atomic then
        raise;  -- all-or-nothing: abort the whole call, nothing is written
      end if;
      v_results := v_results || jsonb_build_array(
        jsonb_build_object('i', v_i, 'ok', false, 'error', sqlerrm));
    end;
    v_i := v_i + 1;
  end loop;

  v_state := v_row.live_state;
  if v_ok > 0 then
    v_ls := jsonb_set(v_ls, '{matchState}', v_ms, true);
    -- First real start moves the tournament to Running (same rule as the old setMatchState).
    if v_started
       and coalesce(v_row.live_state, '') not in ('in_progress', 'finished')
       and coalesce(v_row.status, '') not in ('completed', 'archived') then
      v_state := 'in_progress';
    end if;
    update public.tournaments
    set live_settings = v_ls,
        live_state = v_state,
        updated_at = now()
    where id = p_tournament_id;
  end if;

  return jsonb_build_object('live_settings', v_ls, 'live_state', v_state, 'results', v_results);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.elim_merge_live_settings(p_tournament_id bigint, p_set jsonb, p_remove text[] DEFAULT '{}'::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_row record;
  v_ls  jsonb;
  v_owned constant text[] := array['matchState', 'queueOrder', 'autoAssignMode', 'autoAssignEnabled',
                                   'queuePins', 'bracket', 'drawLog'];
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;
  if p_tournament_id is null or not public.can_manage_tournament(p_tournament_id) then
    raise exception 'Not allowed to manage this tournament' using errcode = '42501';
  end if;
  if p_set is null or jsonb_typeof(p_set) <> 'object' then
    raise exception 'p_set must be an object' using errcode = '22023';
  end if;
  if exists (select 1 from jsonb_object_keys(p_set) k where k = any(v_owned))
     or coalesce(p_remove, '{}') && v_owned then
    raise exception 'Scheduler-owned live_settings keys cannot be changed here' using errcode = '42501';
  end if;

  select t.live_settings, t.tournament_format into v_row
  from public.tournaments t
  where t.id = p_tournament_id
  for update;
  if not found then
    raise exception 'Tournament not found' using errcode = 'P0002';
  end if;
  if v_row.tournament_format = 'chip-tournament' then
    raise exception 'Not an elimination tournament' using errcode = '22023';
  end if;

  v_ls := (coalesce(v_row.live_settings, '{}'::jsonb) - coalesce(p_remove, '{}')) || p_set;
  update public.tournaments
  set live_settings = v_ls, updated_at = now()
  where id = p_tournament_id;
  return v_ls;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_venue(p_venue jsonb, p_director_ids bigint[] DEFAULT '{}'::bigint[], p_owner_id bigint DEFAULT NULL::bigint)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_me       bigint;
  v_role     text;
  v_is_admin boolean;
  v_owner    bigint;
  v_venue    integer;
  v_dir      bigint;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;
  select id_auto, role into v_me, v_role from public.profiles where id = auth.uid();
  if v_role is null or v_role not in ('bar_owner', 'compete_admin', 'super_admin') then
    raise exception 'Only bar owners and admins can create venues' using errcode = '42501';
  end if;
  v_is_admin := v_role in ('compete_admin', 'super_admin');

  if coalesce(btrim(p_venue->>'venue'), '') = '' or coalesce(btrim(p_venue->>'address'), '') = ''
     or coalesce(btrim(p_venue->>'city'), '') = '' or coalesce(btrim(p_venue->>'state'), '') = ''
     or coalesce(btrim(p_venue->>'zip_code'), '') = '' then
    raise exception 'Venue name, address, city, state and ZIP code are required' using errcode = '22023';
  end if;

  if v_is_admin then
    v_owner := p_owner_id;  -- explicit choice only; never the admin by default
    if v_owner is not null and not exists (
      select 1 from public.profiles where id_auto = v_owner and coalesce(status, 'active') = 'active'
    ) then
      raise exception 'Owner % not found', v_owner using errcode = 'P0002';
    end if;
  else
    if p_owner_id is not null and p_owner_id <> v_me then
      raise exception 'Bar owners can only create venues they own' using errcode = '42501';
    end if;
    v_owner := v_me;
  end if;

  insert into public.venues (venue, address, city, state, zip_code, phone, google_place_id, latitude, longitude, status)
  values (
    p_venue->>'venue', p_venue->>'address', p_venue->>'city', p_venue->>'state', p_venue->>'zip_code',
    nullif(p_venue->>'phone', ''), nullif(p_venue->>'google_place_id', ''),
    nullif(p_venue->>'latitude', '')::numeric, nullif(p_venue->>'longitude', '')::numeric,
    'active')
  returning id into v_venue;

  if v_owner is not null then
    insert into public.venue_owners (venue_id, owner_id, assigned_by, is_primary)
    values (v_venue, v_owner, v_me, true);
    perform public._recompute_user_role(v_owner);
  end if;

  foreach v_dir in array coalesce(p_director_ids, '{}'::bigint[]) loop
    if not exists (select 1 from public.profiles where id_auto = v_dir) then
      raise exception 'Director % not found', v_dir using errcode = 'P0002';
    end if;
    insert into public.venue_directors (venue_id, director_id, assigned_by)
    values (v_venue, v_dir, v_me)
    on conflict (venue_id, director_id) do nothing;
    perform public._recompute_user_role(v_dir);
  end loop;

  return v_venue;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.log_app_event(p_event_type text, p_entity_type text DEFAULT NULL::text, p_entity_id integer DEFAULT NULL::integer, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid uuid := auth.uid();
begin
  if not public._app_event_shape_ok(p_event_type, p_entity_type, coalesce(p_metadata, '{}'::jsonb)) then
    return false;
  end if;
  if not public._app_event_rate_ok() then
    return false;
  end if;
  insert into public.app_events (event_type, entity_type, entity_id, user_id, metadata)
  values (p_event_type, p_entity_type, p_entity_id, v_uid, coalesce(p_metadata, '{}'::jsonb));
  return true;
end
$function$
;

CREATE OR REPLACE FUNCTION public.search_users_for_staff(p_query text, p_limit integer DEFAULT 20, p_include_admins boolean DEFAULT false)
 RETURNS TABLE(id uuid, id_auto bigint, user_name text, name text, role text, email_display text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_role text;
  v_admin boolean;
  v_q text := trim(coalesce(p_query, ''));
  v_pat text;
begin
  select pr.role into v_role from public.profiles pr where pr.id = auth.uid();
  if v_role is null or v_role not in ('tournament_director', 'bar_owner', 'compete_admin', 'super_admin') then
    raise exception 'not authorized' using errcode = '42501';
  end if;
  v_admin := v_role in ('compete_admin', 'super_admin');
  if length(v_q) < 2 then
    return;
  end if;
  v_pat := '%' || replace(replace(replace(v_q, '\', '\\'), '%', '\%'), '_', '\_') || '%';
  return query
    select p.id, p.id_auto, p.user_name, p.name, p.role,
           case when v_admin then p.email else public._mask_email(p.email) end
      from public.profiles p
     where p.status = 'active'
       -- admin accounts are not staff/director candidates unless an ADMIN explicitly asks
       and (p.role not in ('compete_admin', 'super_admin') or (p_include_admins and v_admin))
       and (p.user_name ilike v_pat or p.name ilike v_pat
            -- admins: partial email search; TDs / bar owners: exact email only (no enumeration)
            or (v_admin and p.email ilike v_pat)
            or (not v_admin and lower(p.email) = lower(v_q)))
     order by p.name nulls last, p.user_name
     limit least(greatest(coalesce(p_limit, 20), 1), 50);
end;
$function$
;

CREATE OR REPLACE FUNCTION public._elim_auto_assign_kick(p_tournament_id bigint, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_url    text;
  v_secret text;
begin
  select ds.decrypted_secret into v_url from vault.decrypted_secrets ds where ds.name = 'elim_auto_assign_url';
  select ds.decrypted_secret into v_secret from vault.decrypted_secrets ds where ds.name = 'elim_auto_assign_secret';
  if v_url is null or v_secret is null then
    return;  -- not configured yet: Auto Assign simply doesn't run server-side
  end if;
  perform net.http_post(
    url := v_url,
    body := jsonb_build_object('tournament_id', p_tournament_id, 'reason', p_reason),
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-auto-assign-secret', v_secret),
    timeout_milliseconds := 5000
  );
exception when others then
  -- A failed kick must never fail the TD's / player's write; the sweep recovers.
  raise warning 'elim auto-assign kick failed for tournament %: %', p_tournament_id, sqlerrm;
end;
$function$
;

CREATE OR REPLACE FUNCTION public._elim_auto_assign_on_table()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_ok boolean;
begin
  if NEW.status = 'unavailable' then
    return null;
  end if;
  if TG_OP = 'UPDATE' and OLD.status is distinct from 'unavailable' then
    return null;  -- available ↔ in_use is not an availability change for Auto Assign
  end if;
  select (t.live_settings ->> 'autoAssignEnabled' = 'true'
          and t.live_state = 'in_progress'
          and not coalesce(t.is_paused, false)
          and t.tournament_format <> 'chip-tournament')
  into v_ok
  from public.tournaments t
  where t.id = NEW.tournament_id;
  if coalesce(v_ok, false) then
    perform public._elim_auto_assign_kick(NEW.tournament_id, 'table_available');
  end if;
  return null;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.elim_auto_assign_apply(p_tournament_id bigint, p_ops jsonb, p_expected_updated_at timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_row     record;
  v_ls      jsonb;
  v_ms      jsonb;
  v_ids     text[];
  v_op      jsonb;
  v_step    jsonb;
  v_results jsonb := '[]'::jsonb;
  v_i       int := 0;
  v_ok      int := 0;
  v_now     timestamptz;
begin
  if p_ops is null or jsonb_typeof(p_ops) <> 'array'
     or jsonb_array_length(p_ops) < 1 or jsonb_array_length(p_ops) > 64 then
    raise exception 'ops must be an array of 1..64 operations' using errcode = '22023';
  end if;
  if exists (
    select 1 from jsonb_array_elements(p_ops) e
    where jsonb_typeof(e) <> 'object'
       or (e ->> 'op') is distinct from 'assign'
       or exists (select 1 from jsonb_object_keys(e) k
                  where k not in ('op', 'matchId', 'tableId', 'ifUnassigned', 'start'))
       or (e -> 'ifUnassigned') is distinct from 'true'::jsonb
       or (e ? 'start' and (e -> 'start') is distinct from 'false'::jsonb)
  ) then
    raise exception 'Only automatic assign ops (ifUnassigned, never start) are allowed' using errcode = '42501';
  end if;

  select t.live_settings, t.live_state, t.is_paused, t.tournament_format, t.updated_at
  into v_row
  from public.tournaments t
  where t.id = p_tournament_id
  for update;
  if not found then
    raise exception 'Tournament not found' using errcode = 'P0002';
  end if;
  if coalesce(v_row.live_settings ->> 'autoAssignEnabled', '') <> 'true'
     or v_row.live_state is distinct from 'in_progress'
     or coalesce(v_row.is_paused, false)
     or v_row.tournament_format = 'chip-tournament' then
    return jsonb_build_object('status', 'inactive');
  end if;
  if p_expected_updated_at is null or v_row.updated_at is distinct from p_expected_updated_at then
    return jsonb_build_object('status', 'stale', 'updated_at', v_row.updated_at);
  end if;

  v_ls := coalesce(v_row.live_settings, '{}'::jsonb);
  if jsonb_typeof(v_ls #> '{bracket,graph}') is distinct from 'array' then
    return jsonb_build_object('status', 'inactive');
  end if;
  select coalesce(array_agg(n ->> 'id'), '{}') into v_ids
  from jsonb_array_elements(v_ls #> '{bracket,graph}') n;
  v_ms := case when jsonb_typeof(v_ls -> 'matchState') = 'object'
               then v_ls -> 'matchState' else '{}'::jsonb end;

  for v_op in select value from jsonb_array_elements(p_ops) loop
    begin
      v_step := public._elim_apply_one(p_tournament_id, v_ids, v_ms, v_op);
      v_ms := v_step -> 'ms';
      v_ok := v_ok + 1;
      v_results := v_results || jsonb_build_array(jsonb_build_object('i', v_i, 'ok', true));
    exception when sqlstate 'P0001' then
      v_results := v_results || jsonb_build_array(
        jsonb_build_object('i', v_i, 'ok', false, 'error', sqlerrm));
    end;
    v_i := v_i + 1;
  end loop;

  v_now := v_row.updated_at;
  if v_ok > 0 then
    v_ls := jsonb_set(v_ls, '{matchState}', v_ms, true);
    update public.tournaments
    set live_settings = v_ls, updated_at = now()
    where id = p_tournament_id
    returning updated_at into v_now;
  end if;
  return jsonb_build_object('status', 'applied', 'results', v_results, 'updated_at', v_now);
end;
$function$
;

CREATE OR REPLACE FUNCTION public._elim_auto_assign_sweep()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  r record;
  n integer := 0;
begin
  for r in
    select t.id from public.tournaments t
    where t.live_state = 'in_progress'
      and not coalesce(t.is_paused, false)
      and t.tournament_format <> 'chip-tournament'
      and t.live_settings ->> 'autoAssignEnabled' = 'true'
      and jsonb_typeof(t.live_settings #> '{bracket,graph}') = 'array'
  loop
    perform public._elim_auto_assign_kick(r.id, 'sweep');
    n := n + 1;
  end loop;
  return n;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.set_gameplay_started_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  -- Stamp only on the transition INTO in_progress, and only once (never overwrite / never on
  -- unrelated edits made while already live).
  if new.live_state = 'in_progress'
     and (tg_op = 'INSERT' or old.live_state is distinct from 'in_progress')
     and new.gameplay_started_at is null then
    new.gameplay_started_at := now();
  end if;
  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public._match_player_context(p_tournament_id bigint, p_match_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid     bigint;
  v_player  uuid;
  v_ls      jsonb;
  v_ms      jsonb;
  v_who     jsonb;
  v_reg     bigint;
  v_status  text;
begin
  select p.id_auto into v_uid from public.profiles p where p.id = auth.uid();
  v_player := public.current_player_id();
  if v_uid is null and v_player is null then
    raise exception 'Not signed in' using errcode = '42501';
  end if;

  select t.live_settings into v_ls
  from public.tournaments t
  where t.id = p_tournament_id and t.tournament_format <> 'chip-tournament';
  if v_ls is null then
    raise exception 'Tournament not found' using errcode = 'P0002';
  end if;

  v_who := public._elim_resolve(v_ls) -> p_match_id;
  if v_who is null or not coalesce((v_who ->> 'real')::boolean, false) then
    raise exception 'match_not_playable' using errcode = 'P0001';
  end if;

  -- the caller must BE one of this match's two players
  select tp.id into v_reg
  from public.tournament_players tp
  where tp.tournament_id = p_tournament_id
    and (tp.player_id = v_uid or tp.player_uuid = v_player)
    and tp.status not in ('cancelled', 'no_show')
    and tp.id::text in (v_who ->> 'p1', v_who ->> 'p2');
  if v_reg is null then
    raise exception 'Not a player in this match' using errcode = '42501';
  end if;

  v_ms := coalesce(v_ls #> array['matchState', p_match_id], '{}'::jsonb);
  v_status := coalesce(v_ms ->> 'status', 'scheduled');
  if v_status = 'completed' then
    raise exception 'match_completed' using errcode = 'P0001';
  end if;
  -- NOTE: jsonb_typeof() is NULL for a missing key, and NULL <> 'x' is NULL (not true), so these
  -- MUST use "is distinct from" or an unassigned match would slip through.
  if jsonb_typeof(v_ms -> 'tableId') is distinct from 'number'
     or jsonb_typeof(v_ms -> 'assignedAt') is distinct from 'string' then
    raise exception 'match_not_assigned' using errcode = 'P0001';
  end if;

  return jsonb_build_object(
    'registrationId', v_reg,
    'assignedAt', v_ms ->> 'assignedAt',
    'drawNumber', coalesce((v_ls #>> '{bracket,drawNumber}')::int, 0),
    'tableId', (v_ms ->> 'tableId')::bigint,
    'status', v_status);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.match_contact_td(p_tournament_id bigint, p_match_id text, p_reason text, p_message text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_ctx      jsonb;
  v_row      public.match_player_status;
  v_msg      text := nullif(btrim(coalesce(p_message, '')), '');
  v_name     text;
  v_tname    text;
  v_label    text;
  v_n        int := 0;
  r          record;
begin
  -- pre-match AND mid-match reasons
  if p_reason is null or p_reason not in ('running_late', 'table_missing', 'equipment', 'opponent_not_here', 'dispute', 'watch_shot', 'other') then
    raise exception 'invalid_reason' using errcode = 'P0001';
  end if;
  if v_msg is not null and char_length(v_msg) > 280 then
    raise exception 'message_too_long' using errcode = 'P0001';
  end if;
  v_ctx := public._match_player_context(p_tournament_id, p_match_id);

  insert into public.match_player_status (
    tournament_id, match_id, registration_id, assigned_at, draw_number,
    issue_reason, issue_message, issue_at, resolved_at)
  values (
    p_tournament_id, p_match_id, (v_ctx ->> 'registrationId')::bigint,
    (v_ctx ->> 'assignedAt')::timestamptz, (v_ctx ->> 'drawNumber')::int,
    p_reason, v_msg, now(), null)
  on conflict (tournament_id, match_id, registration_id, assigned_at, draw_number) do update
    -- NOTE: checked_in_at is deliberately NOT touched — raising an issue never un-checks a player.
    set issue_reason = excluded.issue_reason,
        issue_message = excluded.issue_message,
        issue_at = excluded.issue_at,
        issue_pushed_at = null,
        resolved_at = null,
        updated_at = now()
  returning * into v_row;

  select coalesce(nullif(btrim(coalesce(p.first_name, '') || ' ' || coalesce(p.last_name, '')), ''), p.user_name, tp.guest_name, 'A player')
  into v_name
  from public.tournament_players tp
  left join public.profiles p on p.id_auto = tp.player_id
  where tp.id = v_row.registration_id;
  select t.name into v_tname from public.tournaments t where t.id = p_tournament_id;

  v_label := case p_reason
    when 'running_late' then 'Running late'
    when 'table_missing' then 'Can''t find table'
    when 'equipment' then 'Equipment issue'
    when 'opponent_not_here' then 'Opponent not here'
    when 'dispute' then 'Dispute / Need TD'
    when 'watch_shot' then 'Need shot watched'
    else 'Needs help' end;

  for r in select * from public._match_issue_recipients(p_tournament_id) loop
    insert into public.notifications (user_id, title, body, category, data, status, sent_at)
    values (
      r.id_auto,
      coalesce(v_tname, 'Compete'),
      v_name || ' — ' || v_label || coalesce(': ' || v_msg, ''),
      'tournament_update',
      jsonb_build_object(
        'type', 'match_issue', 'tournament_id', p_tournament_id, 'match_id', p_match_id,
        'registration_id', v_row.registration_id, 'assigned_at', v_row.assigned_at,
        'reason', p_reason,
        'deep_link', '/(tabs)/admin/manage-tournament/' || p_tournament_id::text),
      'sent', now());
    v_n := v_n + 1;
  end loop;

  return jsonb_build_object(
    'status', 'sent', 'statusId', v_row.id, 'recipients', v_n,
    'registrationId', v_row.registration_id, 'assignedAt', v_row.assigned_at, 'reason', p_reason);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.match_player_start(p_tournament_id bigint, p_match_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_ctx      jsonb;
  v_row      record;
  v_ls       jsonb;
  v_ms       jsonb;
  v_ids      text[];
  v_step     jsonb;
  v_state    text;
  v_required boolean;
  v_present  int;
  v_reg      bigint;
begin
  -- Participant + current-assignment checks (same resolver as check-in): the caller must be one
  -- of THIS match's two players, the match must be playable, assigned and not completed.
  v_ctx := public._match_player_context(p_tournament_id, p_match_id);
  v_reg := (v_ctx ->> 'registrationId')::bigint;
  if (v_ctx ->> 'status') = 'in_progress' then
    raise exception 'match_in_progress' using errcode = 'P0001';
  end if;

  select t.live_settings, t.live_state, t.status, t.tournament_format
  into v_row
  from public.tournaments t
  where t.id = p_tournament_id
  for update;
  if not found then
    raise exception 'Tournament not found' using errcode = 'P0002';
  end if;
  v_ls := coalesce(v_row.live_settings, '{}'::jsonb);

  -- Check-in gate: only when the TD requires it. Each side must be present, by their own tap or a
  -- manager's manual mark — the opponent can never check someone in.
  v_required := coalesce((v_ls #>> '{checkIn,required}')::boolean, false);
  if v_required then
    select count(*) into v_present
    from public.match_player_status s
    where s.tournament_id = p_tournament_id
      and s.match_id = p_match_id
      and s.assigned_at = (v_ctx ->> 'assignedAt')::timestamptz
      and s.draw_number = (v_ctx ->> 'drawNumber')::int
      and s.checked_in_at is not null;
    if v_present < 2 then
      raise exception 'waiting_for_check_in' using errcode = 'P0001';
    end if;
  end if;

  select coalesce(array_agg(n ->> 'id'), '{}') into v_ids
  from jsonb_array_elements(v_ls #> '{bracket,graph}') n;
  v_ms := case when jsonb_typeof(v_ls -> 'matchState') = 'object' then v_ls -> 'matchState' else '{}'::jsonb end;

  -- Same op, same validation, same server timestamp as the TD path.
  v_step := public._elim_apply_one(p_tournament_id, v_ids, v_ms,
                                   jsonb_build_object('op', 'start', 'matchId', p_match_id));
  v_ls := jsonb_set(v_ls, '{matchState}', v_step -> 'ms', true);

  v_state := v_row.live_state;
  if coalesce(v_row.live_state, '') not in ('in_progress', 'finished')
     and coalesce(v_row.status, '') not in ('completed', 'archived') then
    v_state := 'in_progress';
  end if;

  update public.tournaments
  set live_settings = v_ls, live_state = v_state, updated_at = now()
  where id = p_tournament_id;

  return jsonb_build_object('status', 'started', 'matchId', p_match_id,
                            'startedBy', v_reg, 'liveState', v_state);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.match_mark_checked_in(p_tournament_id bigint, p_match_id text, p_registration_id bigint, p_checked_in boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_ls   jsonb;
  v_ms   jsonb;
  v_who  jsonb;
  v_at   timestamptz;
  v_draw int;
  v_row  public.match_player_status;
begin
  if not public.can_manage_tournament(p_tournament_id) then
    raise exception 'Not allowed to manage this tournament' using errcode = '42501';
  end if;

  select coalesce(t.live_settings, '{}'::jsonb) into v_ls
  from public.tournaments t where t.id = p_tournament_id and t.tournament_format <> 'chip-tournament';
  if v_ls is null then
    raise exception 'Tournament not found' using errcode = 'P0002';
  end if;

  -- The registration must really be one of this match's two sides, on the CURRENT assignment.
  v_who := public._elim_resolve(v_ls) -> p_match_id;
  if v_who is null or not coalesce((v_who ->> 'real')::boolean, false)
     or p_registration_id::text not in (v_who ->> 'p1', v_who ->> 'p2') then
    raise exception 'not_in_match' using errcode = 'P0001';
  end if;
  v_ms := coalesce(v_ls #> array['matchState', p_match_id], '{}'::jsonb);
  if jsonb_typeof(v_ms -> 'assignedAt') is distinct from 'string' then
    raise exception 'match_not_assigned' using errcode = 'P0001';
  end if;
  v_at := (v_ms ->> 'assignedAt')::timestamptz;
  v_draw := coalesce((v_ls #>> '{bracket,drawNumber}')::int, 0);

  if p_checked_in then
    insert into public.match_player_status (
      tournament_id, match_id, registration_id, assigned_at, draw_number,
      checked_in_at, checked_in_by, checked_in_source)
    values (p_tournament_id, p_match_id, p_registration_id, v_at, v_draw, now(), auth.uid(), 'manager')
    on conflict (tournament_id, match_id, registration_id, assigned_at, draw_number) do update
      set checked_in_at = coalesce(public.match_player_status.checked_in_at, excluded.checked_in_at),
          checked_in_by = coalesce(public.match_player_status.checked_in_by, excluded.checked_in_by),
          checked_in_source = coalesce(public.match_player_status.checked_in_source, excluded.checked_in_source),
          updated_at = now()
    returning * into v_row;
  else
    -- Undo: clears presence only. An open Contact TD message is left exactly as it is.
    update public.match_player_status s
    set checked_in_at = null, checked_in_by = null, checked_in_source = null, updated_at = now()
    where s.tournament_id = p_tournament_id and s.match_id = p_match_id
      and s.registration_id = p_registration_id
      and s.assigned_at = v_at and s.draw_number = v_draw
    returning * into v_row;
  end if;

  return jsonb_build_object(
    'status', case when p_checked_in then 'checked_in' else 'cleared' end,
    'registrationId', p_registration_id,
    'checkedInAt', v_row.checked_in_at,
    'source', v_row.checked_in_source);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.match_extend_deadline(p_tournament_id bigint, p_match_id text, p_minutes integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_ls   jsonb;
  v_ms   jsonb;
  v_at   timestamptz;
  v_draw int;
  v_row  public.match_assignment_status;
begin
  if not public.can_manage_tournament(p_tournament_id) then
    raise exception 'Not allowed to manage this tournament' using errcode = '42501';
  end if;
  if p_minutes is null or p_minutes < 1 or p_minutes > 120 then
    raise exception 'invalid_minutes' using errcode = 'P0001';
  end if;

  select coalesce(t.live_settings, '{}'::jsonb) into v_ls
  from public.tournaments t where t.id = p_tournament_id;
  if v_ls is null then
    raise exception 'Tournament not found' using errcode = 'P0002';
  end if;
  v_ms := coalesce(v_ls #> array['matchState', p_match_id], '{}'::jsonb);
  if jsonb_typeof(v_ms -> 'assignedAt') is distinct from 'string' then
    raise exception 'match_not_assigned' using errcode = 'P0001';
  end if;
  v_at := (v_ms ->> 'assignedAt')::timestamptz;
  v_draw := coalesce((v_ls #>> '{bracket,drawNumber}')::int, 0);

  insert into public.match_assignment_status (
    tournament_id, match_id, assigned_at, draw_number, extended_minutes, extended_by, extended_at)
  values (p_tournament_id, p_match_id, v_at, v_draw, least(p_minutes, 240), auth.uid(), now())
  on conflict (tournament_id, match_id, assigned_at, draw_number) do update
    -- extensions accumulate for this assignment; a new assignment starts at 0 (no row)
    set extended_minutes = least(public.match_assignment_status.extended_minutes + excluded.extended_minutes, 240),
        extended_by = excluded.extended_by,
        extended_at = now(),
        -- the deadline moved, so the Forfeit Review alert may fire again later
        review_alert_at = null,
        review_pushed_at = null,
        updated_at = now()
  returning * into v_row;

  return jsonb_build_object('status', 'extended', 'extendedMinutes', v_row.extended_minutes,
                            'assignedAt', v_row.assigned_at);
end;
$function$
;

CREATE OR REPLACE FUNCTION public._match_review_sweep()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  t        record;
  m        record;
  v_at     timestamptz;
  v_draw   int;
  v_ext    int;
  v_due    timestamptz;
  v_alerted timestamptz;
  v_label  text;
  v_n      int := 0;
  r        record;
  v_kicked boolean;
begin
  for t in
    select tt.id, tt.name, tt.live_settings,
           coalesce((tt.live_settings #>> '{checkIn,forfeitReviewAfterMinutes}')::int, 10) review_min,
           coalesce((tt.live_settings #>> '{bracket,drawNumber}')::int, 0) draw
    from public.tournaments tt
    where tt.live_state = 'in_progress'
      and not coalesce(tt.is_paused, false)
      and tt.tournament_format <> 'chip-tournament'
      and coalesce(tt.live_settings #>> '{checkIn,required}', 'false') = 'true'
      and jsonb_typeof(tt.live_settings -> 'matchState') = 'object'
  loop
    v_kicked := false;
    for m in
      select key match_id, value ms
      from jsonb_each(t.live_settings -> 'matchState')
      where jsonb_typeof(value) = 'object'
        -- still waiting: assigned, has a table, NOT started and not finished
        and jsonb_typeof(value -> 'assignedAt') = 'string'
        and jsonb_typeof(value -> 'tableId') = 'number'
        and coalesce(value ->> 'status', 'scheduled') = 'scheduled'
    loop
      v_at := (m.ms ->> 'assignedAt')::timestamptz;
      v_draw := t.draw;
      select coalesce(a.extended_minutes, 0), a.review_alert_at
      into v_ext, v_alerted
      from public.match_assignment_status a
      where a.tournament_id = t.id and a.match_id = m.match_id
        and a.assigned_at = v_at and a.draw_number = v_draw;
      v_ext := coalesce(v_ext, 0);
      v_due := v_at + make_interval(mins => greatest(t.review_min, 1) + v_ext);
      if v_alerted is not null or now() < v_due then
        continue;
      end if;

      -- Stamp FIRST (unique per assignment) so cron can never alert twice.
      insert into public.match_assignment_status (
        tournament_id, match_id, assigned_at, draw_number, review_alert_at)
      values (t.id, m.match_id, v_at, v_draw, now())
      on conflict (tournament_id, match_id, assigned_at, draw_number) do update
        set review_alert_at = now(), updated_at = now()
        where public.match_assignment_status.review_alert_at is null;
      if not found then
        continue;  -- another sweep won the race
      end if;

      select case when count(*) filter (where s.checked_in_at is not null) >= 2
                  then 'not started' else 'players not checked in' end
      into v_label
      from public.match_player_status s
      where s.tournament_id = t.id and s.match_id = m.match_id
        and s.assigned_at = v_at and s.draw_number = v_draw;

      -- In-app for the people running THIS event (same recipients + per-user dedupe as an issue).
      for r in select * from public._match_issue_recipients(t.id) loop
        insert into public.notifications (user_id, title, body, category, data, status, sent_at)
        values (
          r.id_auto,
          coalesce(t.name, 'Compete'),
          'Forfeit Review — ' || m.match_id || ' (' || coalesce(v_label, 'not started') || ')',
          'tournament_update',
          jsonb_build_object(
            'type', 'match_review', 'tournament_id', t.id, 'match_id', m.match_id,
            'assigned_at', v_at,
            'deep_link', '/(tabs)/admin/manage-tournament/' || t.id::text ||
                         '?reviewMatch=' || m.match_id),
          'sent', now());
      end loop;
      v_n := v_n + 1;
      v_kicked := true;
    end loop;

    -- One kick per tournament; the Edge Function pushes whatever is still unpushed.
    if v_kicked then
      perform public._match_review_kick(t.id);
    end if;
  end loop;
  return v_n;
end;
$function$
;

CREATE OR REPLACE FUNCTION public._match_review_kick(p_tournament_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_url    text;
  v_secret text;
begin
  select ds.decrypted_secret into v_url from vault.decrypted_secrets ds where ds.name = 'elim_review_url';
  select ds.decrypted_secret into v_secret from vault.decrypted_secrets ds where ds.name = 'elim_auto_assign_secret';
  if v_url is null or v_secret is null then
    return;  -- not configured: the in-app alert still stands, only the push is skipped
  end if;
  perform net.http_post(
    url := v_url,
    body := jsonb_build_object('tournament_id', p_tournament_id),
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-auto-assign-secret', v_secret),
    timeout_milliseconds := 5000);
exception when others then
  raise warning 'match review kick failed for tournament %: %', p_tournament_id, sqlerrm;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.link_referral_visit(p_visit_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_me       bigint := public._authz_my_id_auto();
  v_referral bigint;
  v_referrer bigint;
  n          int;
begin
  if v_me is null then
    return false;
  end if;
  select id, referrer_profile_id into v_referral, v_referrer
    from public.referrals where referred_profile_id = v_me;
  if v_referral is null or v_referrer is null then
    return false;
  end if;

  update public.referral_visits v
     set referral_id = v_referral
   where v.id = p_visit_id
     and v.referral_id is null
     and v.created_at > now() - interval '30 days'
     and exists (select 1 from public.referral_codes rc
                  where rc.id = v.referral_code_id and rc.profile_id = v_referrer);
  get diagnostics n = row_count;
  return n > 0;
end
$function$
;

CREATE OR REPLACE FUNCTION public.approve_registration_with_fargo(p_registration_id bigint, p_fargo integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_tid    bigint;
  v_pid    bigint;
  v_caller bigint;
  v_role   text;
begin
  select tournament_id, player_id
    into v_tid, v_pid
  from public.tournament_players
  where id = p_registration_id;

  if v_tid is null then
    raise exception 'Registration % not found', p_registration_id;
  end if;

  select id_auto, role
    into v_caller, v_role
  from public.profiles
  where id = auth.uid();

  if not exists (
    select 1
    from public.tournaments t
    where t.id = v_tid
      and (
        t.director_id = v_caller
        or v_role in ('compete_admin', 'super_admin')
      )
  ) then
    raise exception 'Not authorized to approve registrations for this tournament';
  end if;

  -- 1–4: the confirmed Fargo becomes the player's verified profile Fargo.
  -- Skipped for guest registrations (no linked account).
  if v_pid is not null then
    update public.profiles
    set fargo                  = p_fargo,
        fargo_status           = 'verified',
        fargo_last_verified_at = now(),
        fargo_verified_by      = v_caller
    where id_auto = v_pid;
  end if;

  -- 5–6: freeze the snapshot for this event and mark the registration approved.
  update public.tournament_players
  set fargo_at_registration = p_fargo,
      fargo_rating          = p_fargo,
      status                = 'approved',
      updated_at            = now()
  where id = p_registration_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_team(p_tournament_id bigint, p_captain_fargo integer)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_caller bigint; v_caller_player uuid; v_team bigint;
begin
  v_caller := public._team_caller();
  v_caller_player := public.current_player_id();
  if v_caller is null then raise exception 'You must be signed in to register a team'; end if;

  if exists (
    select 1 from public.tournament_team_members m
    where m.tournament_id = p_tournament_id
      and (m.player_id = v_caller or m.player_uuid = v_caller_player)
      and m.invite_status <> 'declined'
  ) then
    raise exception 'You are already on a team for this tournament';
  end if;

  insert into public.tournament_teams (tournament_id, captain_id, status)
  values (p_tournament_id, v_caller, 'pending_partner')
  returning id into v_team;

  insert into public.tournament_team_members
    (team_id, tournament_id, player_id, role, invite_status, is_verified, suggested_fargo)
  values (v_team, p_tournament_id, v_caller, 'captain', 'accepted', true, p_captain_fargo);

  return v_team;
end; $function$
;

CREATE OR REPLACE FUNCTION public.cancel_team_partner(p_team_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_caller bigint; v_caller_player uuid; v_captain bigint; v_captain_uuid uuid; v_locked boolean;
begin
  v_caller := public._team_caller();
  v_caller_player := public.current_player_id();
  select captain_id, captain_player_id, locked into v_captain, v_captain_uuid, v_locked from public.tournament_teams where id = p_team_id;
  if v_captain is null then raise exception 'Team not found'; end if;
  if not (coalesce(v_captain = v_caller, false) or coalesce(v_captain_uuid = v_caller_player, false)) then
    raise exception 'Only the captain can change the partner';
  end if;
  if v_locked then raise exception 'This team is locked — ask the director to unlock it'; end if;
  delete from public.tournament_team_members where team_id = p_team_id and role <> 'captain';
  perform public._recompute_team_status(p_team_id);
end; $function$
;

