CREATE OR REPLACE FUNCTION public.get_team_invite_by_token(p_token text)
 RETURNS TABLE(team_id bigint, tournament_id bigint, tournament_name text, captain_name text, captain_fargo integer, team_status text, is_valid boolean, reason text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_team_id  bigint;
  v_tid      bigint;
  v_status   text;
  v_captain  bigint;
  v_tname    text;
  v_tstatus  text;
  v_tlive    text;
  v_cname    text;
  v_cfargo   int;
begin
  select tt.id, tt.tournament_id, tt.status, tt.captain_id
    into v_team_id, v_tid, v_status, v_captain
  from public.tournament_teams tt
  where tt.invite_token = p_token;

  if not found then
    return query select null::bigint, null::bigint, null::text, null::text, null::int, null::text,
                        false, 'This invite link is invalid.'::text;
    return;
  end if;

  select t.name, t.status, t.live_state
    into v_tname, v_tstatus, v_tlive
  from public.tournaments t where t.id = v_tid;

  select coalesce(nullif(trim(coalesce(pr.first_name, '') || ' ' || coalesce(pr.last_name, '')), ''), pr.name, pr.user_name)
    into v_cname
  from public.profiles pr where pr.id_auto = v_captain;

  select coalesce(cm.fargo_at_registration, pr.fargo, cm.suggested_fargo)
    into v_cfargo
  from public.tournament_team_members cm
  left join public.profiles pr on pr.id_auto = cm.player_id
  where cm.team_id = v_team_id and cm.role = 'captain'
  limit 1;

  team_id         := v_team_id;
  tournament_id   := v_tid;
  tournament_name := coalesce(v_tname, 'this tournament');
  captain_name    := coalesce(v_cname, 'A player');
  captain_fargo   := v_cfargo;
  team_status     := v_status;

  if v_tname is null then
    is_valid := false; reason := 'This tournament could not be found.';
  elsif v_tstatus = 'completed' or v_tlive = 'finished' then
    is_valid := false; reason := 'This tournament has ended.';
  elsif v_status = 'registered' then
    is_valid := false; reason := 'This team is already full.';
  else
    is_valid := true; reason := null::text;
  end if;

  return next;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.tg_giveaway_entries_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_mode text;
begin
  select entry_mode into v_mode from public.giveaways where id = new.giveaway_id;
  if v_mode = 'wallet' then
    if public._giveaway_op() <> 'wallet_entry' then
      raise exception 'wallet giveaway entries can only be created through enter_wallet_giveaway'
        using errcode = '42501';
    end if;
  elsif new.quantity <> 1 then
    raise exception 'legacy giveaway entries always have quantity 1' using errcode = '23514';
  end if;
  if tg_op = 'UPDATE' and (new.giveaway_id <> old.giveaway_id or new.user_id <> old.user_id) then
    raise exception 'giveaway entries cannot be moved' using errcode = '42501';
  end if;
  return new;
end
$function$
;

CREATE OR REPLACE FUNCTION public.admin_grant_giveaway_entries(p_profile_id bigint, p_amount integer, p_note text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_me bigint := public._authz_my_id_auto(); v_res jsonb;
begin
  if not public._giveaway_is_admin() then
    raise exception 'not authorized' using errcode = '42501';
  end if;
  if p_amount is null or p_amount < 1 or p_amount > 10000 then
    return jsonb_build_object('ok', false, 'status', 'invalid_amount');
  end if;
  if not exists (select 1 from public.profiles where id_auto = p_profile_id) then
    return jsonb_build_object('ok', false, 'status', 'no_such_user');
  end if;
  v_res := public._giveaway_wallet_apply(p_profile_id, p_amount, 'admin_grant', null, null,
             case when p_idempotency_key is null then null else 'admin_grant:' || p_idempotency_key end,
             v_me, nullif(btrim(p_note), ''));
  return jsonb_build_object('ok', true,
    'status', case when (v_res->>'duplicate')::boolean then 'duplicate' else 'granted' end,
    'balance', (v_res->>'balance')::int);
end
$function$
;

