CREATE OR REPLACE FUNCTION public.remove_venue_team_member(p_kind text, p_row_id integer)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_venue   integer;
  v_user    bigint;
  v_primary boolean;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;

  if p_kind = 'owner' then
    select venue_id, owner_id, coalesce(is_primary, false) into v_venue, v_user, v_primary
    from public.venue_owners where id = p_row_id for update;
  elsif p_kind = 'director' then
    select venue_id, director_id, false into v_venue, v_user, v_primary
    from public.venue_directors where id = p_row_id for update;
  else
    raise exception 'Invalid kind %', p_kind using errcode = '22023';
  end if;

  if v_venue is null then
    raise exception 'Team member not found' using errcode = 'P0002';
  end if;
  if not (public._authz_is_admin() or public.is_venue_owner(v_venue)) then
    raise exception 'Not authorized to manage this venue''s team' using errcode = '42501';
  end if;
  if v_primary then
    raise exception 'The primary owner cannot be removed' using errcode = '42501';
  end if;

  if p_kind = 'owner' then
    delete from public.venue_owners where id = p_row_id;
  else
    delete from public.venue_directors where id = p_row_id;
  end if;

  return public._recompute_user_role(v_user);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.enable_sms_alerts(p_source text, p_version text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid         uuid := auth.uid();
  v_phone       text;
  v_verified    timestamptz;
  v_was_enabled boolean;
  v_old_version text;
begin
  if v_uid is null then
    raise exception 'Not authenticated';
  end if;
  -- Clients may only claim these sources; privileged sources are server-only.
  if p_source not in ('app_settings', 'onboarding', 'web_opt_in') then
    raise exception 'Invalid consent source';
  end if;

  select phone_number, phone_verified_at into v_phone, v_verified
  from public.profiles where id = v_uid;

  if v_verified is null then
    raise exception 'Phone must be verified before enabling SMS';
  end if;

  if not exists (select 1 from public.notification_preferences where user_id = v_uid) then
    insert into public.notification_preferences (user_id) values (v_uid);
  end if;

  select sms_enabled, sms_consent_version into v_was_enabled, v_old_version
  from public.notification_preferences where user_id = v_uid;

  update public.notification_preferences
  set sms_enabled         = true,
      sms_consent_at      = now(),
      sms_consent_source  = p_source,
      sms_consent_version = p_version,
      sms_opted_out_at    = null,          -- approved re-consent clears prior opt-out
      updated_at          = now()
  where user_id = v_uid;

  -- Log an 'opted_in' event ONLY on a real transition (was not enabled) or a
  -- re-consent to a NEW wording version — never a duplicate for an unchanged toggle.
  if v_was_enabled is distinct from true or v_old_version is distinct from p_version then
    insert into public.sms_consent_events(user_id, phone_number, action, consent_version, consent_source)
    values (v_uid, v_phone, 'opted_in', p_version, p_source);
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.disable_sms_alerts()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid         uuid := auth.uid();
  v_phone       text;
  v_was_enabled boolean;
begin
  if v_uid is null then
    raise exception 'Not authenticated';
  end if;

  select phone_number into v_phone from public.profiles where id = v_uid;
  select sms_enabled into v_was_enabled
  from public.notification_preferences where user_id = v_uid;

  update public.notification_preferences
  set sms_enabled = false, sms_opted_out_at = now(), updated_at = now()
  where user_id = v_uid;

  -- Log 'opted_out' ONLY if SMS was actually enabled — no duplicate events when
  -- disabling something already off. phone_number may be NULL (nullable by design).
  if v_was_enabled is true then
    insert into public.sms_consent_events(user_id, phone_number, action, consent_source)
    values (v_uid, v_phone, 'opted_out', 'app_settings');
  end if;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.issue_player_invitation(p_player_id uuid, p_tournament_id bigint, p_ttl_hours integer DEFAULT 168)
 RETURNS TABLE(token text, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_status text;
  v_norm   text;
  v_last   timestamptz;
  v_token  text;
  v_hash   text;
  v_exp    timestamptz := now() + make_interval(hours => greatest(coalesce(p_ttl_hours, 168), 1));
begin
  if not public.can_manage_tournament(p_tournament_id) then
    raise exception 'Not authorized to invite players for this tournament';
  end if;
  select account_status, email_normalized into v_status, v_norm
  from public.players where id = p_player_id;
  if not found then raise exception 'Player not found'; end if;
  if v_status <> 'PENDING' then raise exception 'Only pending players can be invited'; end if;
  if v_norm is null then raise exception 'Player has no email to invite'; end if;

  -- Rate limit: 60s cooldown between sends for this player.
  select max(pi.sent_at) into v_last from public.player_invitations pi where pi.player_id = p_player_id;
  if v_last is not null and v_last > now() - interval '60 seconds' then
    raise exception 'Please wait a moment before resending the invitation' using errcode = '55000';
  end if;

  -- Supersede the current live invite (if any), then issue a new one.
  update public.player_invitations
     set superseded_at = now()
   where player_id = p_player_id and accepted_at is null and superseded_at is null and revoked_at is null;

  v_token := replace(gen_random_uuid()::text, '-', '') || replace(gen_random_uuid()::text, '-', '');
  v_hash  := encode(sha256(v_token::bytea), 'hex');

  insert into public.player_invitations
    (player_id, email_normalized, token_hash, expires_at, created_by_profile_id)
  values
    (p_player_id, v_norm, v_hash, v_exp, auth.uid());

  update public.players set invited_at = coalesce(invited_at, now()) where id = p_player_id;

  return query select v_token, v_exp;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.revoke_player_invitation(p_player_id uuid, p_tournament_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if not public.can_manage_tournament(p_tournament_id) then
    raise exception 'Not authorized to revoke invitations for this tournament';
  end if;
  update public.player_invitations
     set revoked_at = now()
   where player_id = p_player_id and accepted_at is null and superseded_at is null and revoked_at is null;
end;
$function$
;

CREATE OR REPLACE FUNCTION public._ensure_player_for_user(p_uid uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_player      uuid;
  v_owner       uuid;
  v_email       text;
  v_verified    timestamptz;
  v_norm        text;
  v_has_profile boolean := false;
  v_name        text;
  v_first       text;
  v_last        text;
  v_phone       text;
begin
  if p_uid is null then return null; end if;

  select id into v_player from public.players where profile_id = p_uid;
  if v_player is not null then return v_player; end if;

  select u.email, u.email_confirmed_at into v_email, v_verified
  from auth.users u where u.id = p_uid;
  if v_email is null then return null; end if;
  v_norm := lower(btrim(v_email));

  select true, pr.name, pr.first_name, pr.last_name, pr.phone_number
    into v_has_profile, v_name, v_first, v_last, v_phone
  from public.profiles pr where pr.id = p_uid;
  -- SELECT INTO with no row leaves v_has_profile NULL (not false), and `not NULL` never
  -- triggers the early returns below — so signup (email confirmed before the profile exists)
  -- fell through to inserting a players row for a missing profile → FK violation → Auth
  -- "Database error updating user". FOUND is true only when the profile row exists.
  v_has_profile := found;

  select pl.id, pl.profile_id into v_player, v_owner
  from public.players pl where pl.email_normalized = v_norm;

  if v_player is null then
    if not v_has_profile then return null; end if;
    insert into public.players
      (display_name, first_name, last_name, email, phone_e164, account_status, profile_id, activated_at)
    values
      (coalesce(nullif(v_name, ''), nullif(btrim(coalesce(v_first, '') || ' ' || coalesce(v_last, '')), ''), v_email),
       v_first, v_last, v_email, v_phone, 'ACTIVE', p_uid, now())
    returning id into v_player;
    return v_player;
  end if;

  if v_owner is not null then
    if v_owner = p_uid then return v_player; end if;
    return null;
  end if;

  if v_verified is null then return null; end if;
  if not v_has_profile then return null; end if;

  update public.players
     set profile_id = p_uid, account_status = 'ACTIVE', activated_at = coalesce(activated_at, now())
   where id = v_player and profile_id is null;

  -- Preserve the TD-verified Fargo captured while PENDING: promote it to the profile
  -- (keeping the original verifier + timestamp). Only when the pending row carried one,
  -- and never overwrite an already-verified profile Fargo that is NEWER than the pending
  -- one (idempotent: a second run finds equal timestamps + verified status → no-op).
  update public.profiles p
     set fargo = pl.fargo,
         fargo_status = 'verified',
         fargo_verified_by = pl.fargo_verified_by,
         fargo_last_verified_at = coalesce(pl.fargo_last_verified_at, now())
  from public.players pl
  where p.id = p_uid
    and pl.id = v_player
    and pl.fargo is not null
    and (
      p.fargo_status is distinct from 'verified'
      or coalesce(pl.fargo_last_verified_at, 'epoch'::timestamptz)
         > coalesce(p.fargo_last_verified_at, 'epoch'::timestamptz)
    );

  update public.player_invitations
     set accepted_at = now()
   where player_id = v_player and accepted_at is null and superseded_at is null and revoked_at is null;

  -- Link every row that already identifies this (formerly pending) player by players.id to the
  -- account's profile id (chip entries/results, team memberships, registrations). Never raises.
  perform public._link_claimed_player_rows(v_player, p_uid);

  return v_player;
exception when unique_violation then
  select id into v_player from public.players where profile_id = p_uid;
  return v_player;
end;
$function$
;

