CREATE OR REPLACE FUNCTION public.submit_match_state(p_tournament_id bigint, p_match_id text, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid      bigint;
  v_player   uuid;
  v_is_mgr   boolean;
  v_ls       jsonb;
  v_existing jsonb;
  v_clean    jsonb;
  v_who      jsonb;
  v_key      text;
  v_val      jsonb;
  v_allowed  text[];
begin
  select p.id_auto into v_uid
  from public.profiles p
  where p.id = auth.uid();
  v_player := public.current_player_id();

  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;

  v_is_mgr := public.can_manage_tournament(p_tournament_id);

  if p_patch is null or jsonb_typeof(p_patch) <> 'object' then
    raise exception 'Invalid patch' using errcode = '22023';
  end if;

  -- Lifecycle fields are MANAGER-ONLY. A participant scores; starting a match goes through
  -- match_player_start (table + not-started + check-in rules + server-stamped startedAt).
  v_allowed := case when v_is_mgr
    then array['status', 'winner', 'p1Score', 'p2Score', 'startedAt', 'completedAt', 'result']
    else array['winner', 'p1Score', 'p2Score', 'result'] end;
  if not v_is_mgr and (p_patch ? 'status' or p_patch ? 'startedAt' or p_patch ? 'completedAt') then
    raise exception 'Only a tournament manager can change the match lifecycle' using errcode = '42501';
  end if;

  select coalesce(jsonb_object_agg(key, value), '{}'::jsonb)
  into v_clean
  from jsonb_each(p_patch)
  where key = any(v_allowed);

  for v_key, v_val in select key, value from jsonb_each(v_clean) loop
    if (v_key = 'status' and not (jsonb_typeof(v_val) = 'string'
          and (v_val #>> '{}') in ('scheduled', 'in_progress', 'completed')))
       or (v_key = 'winner' and not (jsonb_typeof(v_val) = 'null' or v_val in ('1'::jsonb, '2'::jsonb)))
       or (v_key in ('p1Score', 'p2Score') and jsonb_typeof(v_val) <> 'null' and not (
             jsonb_typeof(v_val) = 'number' and (v_val #>> '{}') ~ '^[0-9]+$'
             and (v_val #>> '{}')::numeric <= 999))
       or (v_key = 'result' and not (jsonb_typeof(v_val) = 'null' or (jsonb_typeof(v_val) = 'string'
             and (v_val #>> '{}') in ('normal', 'forfeit', 'withdraw'))))
       or (v_key in ('startedAt', 'completedAt') and jsonb_typeof(v_val) not in ('null', 'string'))
    then
      raise exception 'Invalid value for %', v_key using errcode = '22023';
    end if;
    if v_key in ('startedAt', 'completedAt') and jsonb_typeof(v_val) = 'string' then
      begin
        perform (v_val #>> '{}')::timestamptz;
      exception when others then
        raise exception 'Invalid value for %', v_key using errcode = '22023';
      end;
    end if;
  end loop;

  select coalesce(t.live_settings, '{}'::jsonb)
  into v_ls
  from public.tournaments t
  where t.id = p_tournament_id
  for update;

  if v_ls is null then
    raise exception 'Tournament not found' using errcode = 'P0002';
  end if;

  v_ls := jsonb_set(v_ls, '{matchState}', coalesce(v_ls -> 'matchState', '{}'::jsonb), true);
  v_existing := coalesce(v_ls #> array['matchState', p_match_id], '{}'::jsonb);

  if not v_is_mgr then
    v_who := public._elim_resolve(v_ls) -> p_match_id;
    if v_who is null
       or not coalesce((v_who ->> 'real')::boolean, false)
       or not exists (
         select 1 from public.tournament_players tp
         where tp.tournament_id = p_tournament_id
           and (tp.player_id = v_uid or tp.player_uuid = v_player)
           and tp.status not in ('cancelled', 'no_show')
           and tp.id::text in (v_who ->> 'p1', v_who ->> 'p2')
       ) then
      raise exception 'Not allowed to score this match' using errcode = '42501';
    end if;
    if (v_existing ->> 'status') = 'completed' then
      raise exception 'Match is final and locked' using errcode = '42501';
    end if;
  end if;

  v_ls := jsonb_set(v_ls, array['matchState', p_match_id], v_existing || v_clean, true);

  update public.tournaments
  set live_settings = v_ls,
      updated_at = now()
  where id = p_tournament_id;

  return v_ls;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.respond_to_team_invite(p_team_id bigint, p_accept boolean, p_fargo integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_caller bigint; v_caller_player uuid; v_tid bigint; v_mid bigint;
begin
  v_caller := public._team_caller();
  v_caller_player := public.current_player_id();
  select id, tournament_id into v_mid, v_tid
  from public.tournament_team_members
  where team_id = p_team_id and (player_id = v_caller or player_uuid = v_caller_player) and role = 'member';
  if v_mid is null then raise exception 'No invite found for you on this team'; end if;

  if p_accept then
    if exists (
      select 1 from public.tournament_team_members m
      where m.tournament_id = v_tid and (m.player_id = v_caller or m.player_uuid = v_caller_player)
        and m.invite_status = 'accepted' and m.team_id <> p_team_id
    ) then
      raise exception 'You are already on another team for this tournament';
    end if;
    update public.tournament_team_members
      set invite_status = 'accepted', is_verified = true, suggested_fargo = p_fargo, updated_at = now()
      where id = v_mid;
    update public.tournament_teams set locked = true, updated_at = now() where id = p_team_id;
  else
    update public.tournament_team_members
      set invite_status = 'declined', updated_at = now()
      where id = v_mid;
  end if;

  perform public._recompute_team_status(p_team_id);
end; $function$
;

CREATE OR REPLACE FUNCTION public.create_pending_player(p_tournament_id bigint, p_first_name text, p_last_name text, p_email text, p_phone text DEFAULT NULL::text)
 RETURNS TABLE(player_id uuid, outcome text, account_status text, display_name text, email_masked text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_first text := btrim(coalesce(p_first_name, ''));
  v_last  text := btrim(coalesce(p_last_name, ''));
  v_email text := btrim(coalesce(p_email, ''));
  v_norm  text := lower(btrim(coalesce(p_email, '')));
  v_phone text := nullif(btrim(coalesce(p_phone, '')), '');
  v_ex    public.players%rowtype;
  v_new   uuid;
begin
  if not public.can_manage_tournament(p_tournament_id) then
    raise exception 'Not authorized to create players for this tournament';
  end if;
  if v_first = '' or v_last = '' then
    raise exception 'First and last name are required';
  end if;
  if v_email = '' or v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$' then
    raise exception 'A valid email is required';
  end if;

  -- Find-or-reuse by normalized email (partial unique index guarantees at most one).
  select * into v_ex from public.players where email_normalized = v_norm;
  if found then
    if v_ex.account_status = 'DISABLED' then
      raise exception 'An account with this email is disabled; contact an admin'
        using errcode = 'check_violation';
    end if;
    return query select
      v_ex.id,
      case when v_ex.account_status = 'ACTIVE' then 'MATCHED_ACTIVE' else 'MATCHED_PENDING' end,
      v_ex.account_status,
      v_ex.display_name,
      public.mask_email(v_ex.email);
    return;
  end if;

  -- Create a fresh PENDING player. email_normalized is a generated column; never set it.
  begin
    insert into public.players
      (display_name, first_name, last_name, email, phone_e164, account_status, created_by_profile_id)
    values
      (v_first || ' ' || v_last, v_first, v_last, v_email, v_phone, 'PENDING', auth.uid())
    returning id into v_new;
  exception when unique_violation then
    -- Lost a race: reuse whoever landed first (never a second identity).
    select * into v_ex from public.players where email_normalized = v_norm;
    if v_ex.account_status = 'DISABLED' then
      raise exception 'An account with this email is disabled; contact an admin'
        using errcode = 'check_violation';
    end if;
    return query select
      v_ex.id,
      case when v_ex.account_status = 'ACTIVE' then 'MATCHED_ACTIVE' else 'MATCHED_PENDING' end,
      v_ex.account_status, v_ex.display_name, public.mask_email(v_ex.email);
    return;
  end;

  return query select v_new, 'CREATED_PENDING'::text, 'PENDING'::text,
                      v_first || ' ' || v_last, public.mask_email(v_email);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.register_player_for_tournament(p_tournament_id bigint, p_player_id uuid, p_fargo integer DEFAULT NULL::integer, p_status text DEFAULT 'approved'::text)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_profile_id uuid;
  v_status     text;
  v_id_auto    bigint;
  v_existing   bigint;
  v_reg_id     bigint;
begin
  if not public.can_manage_tournament(p_tournament_id) then
    raise exception 'Not authorized to register players for this tournament';
  end if;

  select profile_id, account_status into v_profile_id, v_status
  from public.players where id = p_player_id;
  if not found then raise exception 'Player not found'; end if;
  if v_status = 'DISABLED' then raise exception 'Cannot register a disabled player'; end if;

  if v_profile_id is not null then
    select id_auto into v_id_auto from public.profiles where id = v_profile_id;
  end if;

  select id into v_existing
  from public.tournament_players
  where tournament_id = p_tournament_id and player_uuid = p_player_id and status <> 'cancelled'
  limit 1;
  if v_existing is not null then
    return v_existing;  -- idempotent
  end if;

  insert into public.tournament_players
    (tournament_id, player_id, player_uuid, status, fargo_rating)
  values
    (p_tournament_id, v_id_auto, p_player_id, p_status, p_fargo)
  returning id into v_reg_id;

  return v_reg_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.set_team_name(p_team_id bigint, p_name text)
 RETURNS void
 LANGUAGE plpgsql
