CREATE OR REPLACE FUNCTION public.td_add_team_member_by_uuid(p_team_id bigint, p_player_id uuid, p_fargo integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_tid        bigint;
  v_profile_id uuid;
  v_status     text;
  v_id_auto    bigint;
begin
  select tournament_id into v_tid from public.tournament_teams where id = p_team_id;
  if v_tid is null then raise exception 'Team not found'; end if;
  if not public.can_manage_tournament(v_tid) then
    raise exception 'Not authorized to edit teams for this tournament';
  end if;

  select profile_id, account_status into v_profile_id, v_status
  from public.players where id = p_player_id;
  if not found then raise exception 'Player not found'; end if;
  if v_status = 'DISABLED' then raise exception 'Cannot add a disabled player'; end if;
  if v_profile_id is not null then
    select id_auto into v_id_auto from public.profiles where id = v_profile_id;
  end if;

  if exists (
    select 1 from public.tournament_team_members m
    where m.tournament_id = v_tid
      and m.player_uuid = p_player_id
      and m.invite_status <> 'declined'
  ) then
    raise exception 'That player is already on a team for this tournament';
  end if;

  delete from public.tournament_team_members where team_id = p_team_id and role <> 'captain';
  insert into public.tournament_team_members
    (team_id, tournament_id, player_id, player_uuid, role, invite_status,
     is_verified, suggested_fargo, fargo_at_registration)
  values
    (p_team_id, v_tid, v_id_auto, p_player_id, 'member', 'accepted',
     (p_fargo is not null), p_fargo, p_fargo);

  perform public._promote_verified_fargo(p_player_id, p_fargo);

  update public.tournament_teams set approved = false, locked = true, updated_at = now() where id = p_team_id;
  perform public._recompute_team_status(p_team_id);
end;
$function$
;

CREATE OR REPLACE FUNCTION public.td_verify_player_fargo(p_tournament_id bigint, p_player_id uuid, p_fargo integer)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if not public.can_manage_tournament(p_tournament_id) then
    raise exception 'Not authorized to verify Fargo for this tournament';
  end if;
  if not exists (select 1 from public.players where id = p_player_id) then
    raise exception 'Player not found';
  end if;
  perform public._promote_verified_fargo(p_player_id, p_fargo);
end;
$function$
;

CREATE OR REPLACE FUNCTION public._link_claimed_player_rows(p_player uuid, p_uid uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_id_auto bigint; r record;
begin
  if p_player is null or p_uid is null then return; end if;
  -- Only for the account that actually owns this player record.
  if not exists (select 1 from public.players where id = p_player and profile_id = p_uid) then return; end if;
  select id_auto into v_id_auto from public.profiles where id = p_uid;
  if v_id_auto is null then return; end if;

  for r in select id from public.chip_entries where p1_player_id = p_player and p1_profile_id is null loop
    begin update public.chip_entries set p1_profile_id = v_id_auto where id = r.id; exception when others then null; end;
  end loop;
  for r in select id from public.chip_entries where p2_player_id = p_player and p2_profile_id is null loop
    begin update public.chip_entries set p2_profile_id = v_id_auto where id = r.id; exception when others then null; end;
  end loop;
  for r in select id from public.chip_results where p1_player_id = p_player and p1_profile_id is null loop
    begin update public.chip_results set p1_profile_id = v_id_auto where id = r.id; exception when others then null; end;
  end loop;
  for r in select id from public.chip_results where p2_player_id = p_player and p2_profile_id is null loop
    begin update public.chip_results set p2_profile_id = v_id_auto where id = r.id; exception when others then null; end;
  end loop;
  for r in select id from public.tournament_team_members where player_uuid = p_player and player_id is null loop
    begin update public.tournament_team_members set player_id = v_id_auto where id = r.id; exception when others then null; end;
  end loop;
  for r in select id from public.tournament_players where player_uuid = p_player and player_id is null loop
    begin update public.tournament_players set player_id = v_id_auto where id = r.id; exception when others then null; end;
  end loop;
  for r in select id from public.tournament_teams where captain_player_id = p_player and captain_id is null loop
    begin update public.tournament_teams set captain_id = v_id_auto where id = r.id; exception when others then null; end;
  end loop;
exception when others then
  return; -- never break signup / email confirmation / claim
end; $function$
;

CREATE OR REPLACE FUNCTION public.td_remove_team(p_team_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_tid bigint; v_caller bigint; v_role text;
begin
  select tournament_id into v_tid from public.tournament_teams where id = p_team_id;
  if v_tid is null then raise exception 'Team not found'; end if;
  select id_auto, role into v_caller, v_role from public.profiles where id = auth.uid();
  if not exists (
    select 1 from public.tournaments t
    where t.id = v_tid and (t.director_id = v_caller or v_role in ('compete_admin', 'super_admin'))
  ) then
    raise exception 'Not authorized to edit teams for this tournament';
  end if;
  delete from public.tournament_teams where id = p_team_id; -- members cascade (FK on delete cascade)
end; $function$
;

CREATE OR REPLACE FUNCTION public.claim_pending_player()
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_uid      uuid := auth.uid();
  v_player   uuid;
  v_email    text;
  v_verified timestamptz;
  v_norm     text;
  v_exists   uuid;
  v_owner    uuid;
begin
  if v_uid is null then
    raise exception 'Not authenticated' using errcode = '28000';
  end if;

  -- Links (or confirms already-linked-to-this-account) and returns the player.
  v_player := public._ensure_player_for_user(v_uid);
  if v_player is not null then
    return v_player;
  end if;

  -- Diagnose why linking did not happen — user-safe, no other identity exposed.
  select email, email_confirmed_at into v_email, v_verified from auth.users where id = v_uid;
  if v_verified is null then
    raise exception 'Verify your email to finish setting up your player profile.'
      using errcode = '45001';
  end if;

  v_norm := lower(btrim(coalesce(v_email, '')));
  select id, profile_id into v_exists, v_owner from public.players where email_normalized = v_norm;

  if v_exists is not null and v_owner is not null and v_owner <> v_uid then
    raise exception 'This player profile is already connected to another account. Contact support or a tournament administrator if you believe this is incorrect.'
      using errcode = '45002';
  end if;

  if v_exists is null then
    raise exception 'We could not set up your player profile. Please try again, or contact support.'
      using errcode = '45003';
  end if;

  raise exception 'A conflict prevented linking your player profile. Please contact support.'
    using errcode = '45004';
end;
$function$
;

CREATE OR REPLACE FUNCTION public.tg_guard_venue_director_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if current_user not in ('authenticated', 'anon') then
    return new;
  end if;
  if new.venue_id is not distinct from old.venue_id
     and new.director_id is not distinct from old.director_id then
    return new;
  end if;
  if public._authz_is_admin() then
    return new;
  end if;

  if new.venue_id is distinct from old.venue_id
     and not public._authz_manages_venue(new.venue_id) then
    raise exception 'Not authorized to move this % to venue %', tg_table_name, new.venue_id
      using errcode = '42501';
  end if;

  if new.director_id is distinct from old.director_id
     and not (public.is_venue_owner(old.venue_id) and public.is_venue_owner(new.venue_id)) then
    raise exception 'Only the venue owner or an admin can reassign the director of this %', tg_table_name
      using errcode = '42501';
  end if;

  return new;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.td_create_team_by_uuid(p_tournament_id bigint, p_captain_player_id uuid, p_fargo integer)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_profile_id uuid;
  v_status     text;
  v_id_auto    bigint;
  v_team       bigint;
begin
  if not public.can_manage_tournament(p_tournament_id) then
    raise exception 'Not authorized to add teams for this tournament';
  end if;

  select profile_id, account_status into v_profile_id, v_status
  from public.players where id = p_captain_player_id;
  if not found then raise exception 'Player not found'; end if;
  if v_status = 'DISABLED' then raise exception 'Cannot add a disabled player'; end if;
  if v_profile_id is not null then
    select id_auto into v_id_auto from public.profiles where id = v_profile_id;
  end if;

  if exists (
    select 1 from public.tournament_team_members m
    where m.tournament_id = p_tournament_id
      and m.player_uuid = p_captain_player_id
      and m.invite_status <> 'declined'
  ) then
    raise exception 'That player is already on a team for this tournament';
  end if;

  insert into public.tournament_teams
    (tournament_id, captain_id, captain_player_id, managed_by_profile_id, status)
  values
    (p_tournament_id, v_id_auto, p_captain_player_id, auth.uid(), 'pending_partner')
  returning id into v_team;

  -- TD-entered Fargo is verified at add time: freeze the per-event snapshot (roster
  -- derives fargo_verified from fargo_at_registration); NULL when the TD left it blank.
  insert into public.tournament_team_members
    (team_id, tournament_id, player_id, player_uuid, role, invite_status,
     is_verified, suggested_fargo, fargo_at_registration)
  values
    (v_team, p_tournament_id, v_id_auto, p_captain_player_id, 'captain', 'accepted',
     (p_fargo is not null), p_fargo, p_fargo);

  -- Global promotion (profiles if linked, players if pending). No-op when blank.
  perform public._promote_verified_fargo(p_captain_player_id, p_fargo);

  return v_team;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.create_conversation_with_participants(p_created_by uuid, p_subject text DEFAULT NULL::text, p_category text DEFAULT 'general'::text, p_tournament_id integer DEFAULT NULL::integer, p_is_support boolean DEFAULT false, p_recipient_id uuid DEFAULT NULL::uuid, p_first_message text DEFAULT ''::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_convo_id UUID;
  v_admin RECORD;
BEGIN
  -- 0. The creator must be the authenticated caller (no impersonation)
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Not authenticated' USING ERRCODE = '28000';
  END IF;
  IF p_created_by IS DISTINCT FROM auth.uid() THEN
    RAISE EXCEPTION 'Conversations can only be created as yourself' USING ERRCODE = '42501';
  END IF;
  IF NOT COALESCE(p_is_support, false) AND p_recipient_id = p_created_by THEN
    RAISE EXCEPTION 'You cannot start a conversation with yourself' USING ERRCODE = '22023';
  END IF;

  -- 1. Create conversation
  INSERT INTO conversations (created_by, subject, category, tournament_id, is_support)
  VALUES (p_created_by, p_subject, p_category, p_tournament_id, p_is_support)
  RETURNING id INTO v_convo_id;

  -- 2. Add creator as participant
  INSERT INTO conversation_participants (conversation_id, user_id, last_read_at)
  VALUES (v_convo_id, p_created_by, now());

  -- 3. Add recipient(s)
  IF p_is_support THEN
    -- Add ALL admins
    FOR v_admin IN
      SELECT id FROM profiles
      WHERE role IN ('compete_admin', 'super_admin')
      AND id != p_created_by
    LOOP
      INSERT INTO conversation_participants (conversation_id, user_id)
      VALUES (v_convo_id, v_admin.id);
    END LOOP;
  ELSIF p_recipient_id IS NOT NULL THEN
    INSERT INTO conversation_participants (conversation_id, user_id)
    VALUES (v_convo_id, p_recipient_id);
  END IF;

  -- 4. Send first message
  IF p_first_message != '' THEN
    INSERT INTO conversation_messages (conversation_id, sender_id, body)
    VALUES (v_convo_id, p_created_by, p_first_message);
  END IF;

  RETURN v_convo_id;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.dismiss_tournament_review(p_tournament_id integer)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_id_auto bigint;
  v_id uuid;
begin
  select id_auto into v_id_auto from public.profiles where id = auth.uid();
  if v_id_auto is null then raise exception 'not authenticated'; end if;

  insert into public.tournament_reviews (tournament_id, reviewer_id, reviewer_id_auto, dismissed_at, updated_at)
  values (p_tournament_id, auth.uid(), v_id_auto, now(), now())
  on conflict (tournament_id, reviewer_id) do nothing
  returning id into v_id;

  if v_id is null then
    select id into v_id from public.tournament_reviews
      where tournament_id = p_tournament_id and reviewer_id = auth.uid();
  end if;
  return v_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.submit_tournament_review(p_tournament_id integer, p_rating smallint, p_selected_reasons text[] DEFAULT '{}'::text[], p_comment text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_id_auto bigint;
  v_id uuid;
  v record;
  v_reasons text[];
  v_reason_str text;
begin
  select id_auto into v_id_auto from public.profiles where id = auth.uid();
  if v_id_auto is null then raise exception 'not authenticated'; end if;
  if p_rating is null or p_rating < 1 or p_rating > 5 then raise exception 'rating must be 1..5'; end if;

  if not (
    exists (select 1 from public.tournament_players tp
             where tp.tournament_id = p_tournament_id and tp.player_id = v_id_auto
               and coalesce(tp.status, '') not in ('cancelled', 'no_show'))
    or exists (select 1 from public.tournament_team_members tm
                where tm.tournament_id = p_tournament_id and tm.player_id = v_id_auto
                  and tm.invite_status = 'accepted')
    or exists (select 1 from public.chip_entries ce
                where ce.tournament_id = p_tournament_id
                  and (ce.p1_profile_id = v_id_auto or ce.p2_profile_id = v_id_auto))
  ) then
    raise exception 'not a participant of this tournament';
  end if;

  v_reasons := coalesce(p_selected_reasons, '{}');
  v_reason_str := nullif(array_to_string(v_reasons, ' · '), '');  -- derived search/display projection

  select t.name, t.tournament_date, t.game_type, t.tournament_format, t.venue_id, t.director_id,
         vn.venue as venue_name,
         (select coalesce(nullif(btrim(coalesce(dp.first_name,'') || ' ' || coalesce(dp.last_name,'')), ''),
                          dp.name, dp.user_name)
            from public.profiles dp where dp.id_auto = t.director_id) as director_name
    into v
    from public.tournaments t
    left join public.venues vn on vn.id = t.venue_id
   where t.id = p_tournament_id;

  insert into public.tournament_reviews (
    tournament_id, reviewer_id, reviewer_id_auto, venue_id, tournament_director_id,
    tournament_name, tournament_date, game_type, tournament_format, venue_name, director_name,
    rating, selected_reasons, selected_reason, comment, submitted_at, dismissed_at, updated_at
  ) values (
    p_tournament_id, auth.uid(), v_id_auto, v.venue_id, v.director_id,
    v.name, v.tournament_date, v.game_type, v.tournament_format, v.venue_name, v.director_name,
    p_rating, v_reasons, v_reason_str, p_comment, now(), null, now()
  )
  on conflict (tournament_id, reviewer_id) do update
    set rating = excluded.rating,
        selected_reasons = excluded.selected_reasons,
        selected_reason = excluded.selected_reason,
        comment = excluded.comment,
        submitted_at = now(),
        dismissed_at = null,
        updated_at = now()
    where public.tournament_reviews.submitted_at is null
  returning id into v_id;

  if v_id is null then
    select id into v_id from public.tournament_reviews
      where tournament_id = p_tournament_id and reviewer_id = auth.uid();
  end if;
  return v_id;
end;
$function$
;

CREATE OR REPLACE FUNCTION public.set_review_archived(p_review_id uuid, p_archived boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_conv uuid; v_tid integer;
begin
  select conversation_id, tournament_id into v_conv, v_tid
    from public.tournament_reviews where id = p_review_id;
  if v_tid is null then raise exception 'review not found'; end if;
  if not public.can_view_tournament_reviews(v_tid) then raise exception 'not authorized for this review'; end if;

  if p_archived then
    insert into public.tournament_review_archives (review_id, viewer_id, archived_at)
    values (p_review_id, auth.uid(), now())
    on conflict (review_id, viewer_id) do update set archived_at = now();
  else
    delete from public.tournament_review_archives where review_id = p_review_id and viewer_id = auth.uid();
  end if;

  if v_conv is not null then
    update public.conversation_participants
       set archived_at = case when p_archived then now() else null end
     where conversation_id = v_conv and user_id = auth.uid();
  end if;
end; $function$
;

CREATE OR REPLACE FUNCTION public._referral_ensure_code(p_profile_id bigint)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_code text;
  v_base text;
  v_try  text;
  n      int := 1;
begin
  select code into v_code from public.referral_codes
   where profile_id = p_profile_id and disabled_at is null;
  if v_code is not null then
    return v_code;
  end if;

  select left(upper(regexp_replace(coalesce(user_name, ''), '[^A-Za-z0-9]', '', 'g')), 13)
    into v_base
    from public.profiles where id_auto = p_profile_id;
  if v_base is null then
    return null;                                  -- no such profile
  end if;
  if length(v_base) < 3 then
    v_base := rpad(v_base, 3, 'X');         -- never happens today (usernames are ≥3)
  end if;

  loop
    v_try := case when n = 1 then v_base else v_base || n::text end;
    begin
      insert into public.referral_codes (profile_id, code) values (p_profile_id, v_try);
      return v_try;
    exception when unique_violation then
      -- Either the code is taken, or a concurrent call just gave THIS profile its code.
      select code into v_code from public.referral_codes
       where profile_id = p_profile_id and disabled_at is null;
      if v_code is not null then
        return v_code;
      end if;
      n := n + 1;
      if n > 999 then
        raise exception 'referral code space exhausted for base %', v_base;
      end if;
    end;
  end loop;
end
$function$
;

CREATE OR REPLACE FUNCTION public.tg_profiles_create_referral_code()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  begin
    perform public._referral_ensure_code(new.id_auto);
  exception when others then
    raise warning 'referral code generation failed for profile %: %', new.id_auto, sqlerrm;
  end;
  return new;
end
$function$
;

CREATE OR REPLACE FUNCTION public.get_my_referral_code()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_me bigint := public._authz_my_id_auto();
begin
  if v_me is null then
    return null;
  end if;
  return public._referral_ensure_code(v_me);
end
$function$
;

CREATE OR REPLACE FUNCTION public.tg_giveaways_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_op       text := public._giveaway_op();
  v_sum      bigint;
  v_max_mine integer;
begin
  if tg_op = 'INSERT' then
    if new.status = 'cancelled' then
      raise exception 'giveaways cannot be created cancelled' using errcode = '42501';
    end if;
    -- Wallet giveaways always start as a draft (so the native launch hold in publish_giveaway
    -- can't be skipped by inserting them live).
    if new.entry_mode = 'wallet' and (new.status <> 'draft' or new.winner_id is not null) then
      raise exception 'wallet giveaways must be created as a draft' using errcode = '42501';
    end if;
    -- Older app versions still create legacy giveaways directly as active: stamp them published.
    if new.status = 'active' and new.published_at is null then
      new.published_at := now();
    end if;
    return new;
  end if;

  -- Drafts go live only through publish_giveaway (validation, wallet launch hold, one notification).
  if old.status = 'draft' and new.status not in ('draft', 'archived') and v_op <> 'publish' then
    raise exception 'drafts are published only through publish_giveaway' using errcode = '42501';
  end if;
  -- Nor can a never-published draft become active via archive → Restore.
  if new.status = 'active' and old.status <> 'active' and new.published_at is null and v_op <> 'publish' then
    raise exception 'this giveaway has never been published; use publish_giveaway' using errcode = '42501';
  end if;

  if new.entry_mode is distinct from old.entry_mode
     and exists (select 1 from public.giveaway_entries where giveaway_id = old.id) then
    raise exception 'entry mode cannot change after entries exist' using errcode = '42501';
  end if;

  -- Cancelled is terminal (other columns may still change, e.g. FK SET NULL on cancelled_by).
  if old.status = 'cancelled' and new.status <> 'cancelled' then
    raise exception 'a cancelled giveaway cannot be reopened' using errcode = '42501';
  end if;
  if new.status = 'cancelled' and old.status <> 'cancelled' and v_op <> 'cancel' then
    raise exception 'giveaways can only be cancelled through cancel_wallet_giveaway' using errcode = '42501';
  end if;

  if new.entry_mode = 'wallet' and v_op <> 'draw' then
    -- A winner can be cleared (account deletion) but never set/changed outside the draw function.
    if new.winner_id is not null and new.winner_id is distinct from old.winner_id then
      raise exception 'wallet giveaway winners are drawn only through draw_wallet_giveaway' using errcode = '42501';
    end if;
    if new.status = 'awarded' and old.status <> 'awarded'
       and not (old.status = 'archived' and old.winner_id is not null and new.winner_id = old.winner_id) then
      raise exception 'wallet giveaways are awarded only through draw_wallet_giveaway' using errcode = '42501';
    end if;
  end if;

  if new.entry_mode = 'wallet' then
    if new.status = 'archived' and old.status not in ('archived', 'awarded')
       and exists (select 1 from public.giveaway_entries where giveaway_id = old.id) then
      raise exception 'draw or cancel (refund) a wallet giveaway before archiving it' using errcode = '42501';
    end if;

    select coalesce(sum(quantity), 0), coalesce(max(quantity), 0) into v_sum, v_max_mine
      from public.giveaway_entries where giveaway_id = old.id;
    if coalesce(new.max_entries, 0) < v_sum then
      raise exception 'capacity cannot be lowered below the % entries already in the giveaway', v_sum
        using errcode = '23514';
    end if;
    if new.per_user_max is not null and new.per_user_max < v_max_mine then
      raise exception 'per-user max cannot be lowered below an entrant''s existing % entries', v_max_mine
        using errcode = '23514';
    end if;
  end if;
  return new;
end
$function$
;

CREATE OR REPLACE FUNCTION public._giveaway_wallet_apply(p_profile_id bigint, p_delta integer, p_reason text, p_giveaway_id integer DEFAULT NULL::integer, p_referral_id bigint DEFAULT NULL::bigint, p_idempotency_key text DEFAULT NULL::text, p_created_by bigint DEFAULT NULL::bigint, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_balance integer;
  v_new     integer;
  v_ledger  bigint;
begin
  insert into public.giveaway_wallets (profile_id) values (p_profile_id) on conflict do nothing;
  select balance into v_balance from public.giveaway_wallets where profile_id = p_profile_id for update;

  -- Checked AFTER taking the lock, so a concurrent twin with the same key sees the first commit.
  if p_idempotency_key is not null then
    select id into v_ledger from public.giveaway_credit_ledger where idempotency_key = p_idempotency_key;
    if found then
      return jsonb_build_object('duplicate', true, 'ledger_id', v_ledger, 'balance', v_balance);
    end if;
  end if;

  v_new := v_balance + p_delta;
  if v_new < 0 then
    raise exception 'insufficient_balance' using errcode = 'P0001', detail = v_balance::text;
  end if;

  update public.giveaway_wallets set balance = v_new, updated_at = now() where profile_id = p_profile_id;
  insert into public.giveaway_credit_ledger
    (profile_id, delta, balance_after, reason, giveaway_id, referral_id, idempotency_key, created_by, note)
  values (p_profile_id, p_delta, v_new, p_reason, p_giveaway_id, p_referral_id, p_idempotency_key, p_created_by, p_note)
  returning id into v_ledger;

  return jsonb_build_object('duplicate', false, 'ledger_id', v_ledger, 'balance', v_new);
end
$function$
;

CREATE OR REPLACE FUNCTION public.admin_revoke_giveaway_entries(p_profile_id bigint, p_amount integer, p_note text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_me bigint := public._authz_my_id_auto(); v_res jsonb;
begin
  if not public._giveaway_is_admin() then
    raise exception 'not authorized' using errcode = '42501';
  end if;
  if p_amount is null or p_amount < 1 or p_amount > 10000 then
    return jsonb_build_object('ok', false, 'status', 'invalid_amount');
  end if;
  if nullif(btrim(p_note), '') is null then
    return jsonb_build_object('ok', false, 'status', 'note_required');
  end if;
  begin
    v_res := public._giveaway_wallet_apply(p_profile_id, -p_amount, 'admin_revoke', null, null,
               case when p_idempotency_key is null then null else 'admin_revoke:' || p_idempotency_key end,
               v_me, btrim(p_note));
  exception when sqlstate 'P0001' then
    return jsonb_build_object('ok', false, 'status', 'insufficient_balance',
      'balance', public._giveaway_balance_of(p_profile_id));
  end;
  return jsonb_build_object('ok', true,
    'status', case when (v_res->>'duplicate')::boolean then 'duplicate' else 'revoked' end,
    'balance', (v_res->>'balance')::int);
end
$function$
;

CREATE OR REPLACE FUNCTION public.enter_wallet_giveaway(p_giveaway_id integer, p_quantity integer, p_request_id uuid, p_entrant jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_me     bigint := public._authz_my_id_auto();
  g        public.giveaways%rowtype;
  v_key    text;
  v_total  bigint;
  v_mine   integer;
  v_entry  integer;
  v_res    jsonb;
  v_bday   date;
  v_closed boolean := false;
begin
  if v_me is null then
    return jsonb_build_object('ok', false, 'status', 'not_authenticated');
  end if;
  if p_request_id is null then
    return jsonb_build_object('ok', false, 'status', 'request_id_required');
  end if;
  v_key := 'spend:' || v_me || ':' || p_request_id;

  -- Replay of an already-applied request: report current state, charge nothing.
  if exists (select 1 from public.giveaway_credit_ledger where idempotency_key = v_key) then
    select quantity into v_mine from public.giveaway_entries where giveaway_id = p_giveaway_id and user_id = v_me;
    return jsonb_build_object('ok', true, 'status', 'duplicate', 'my_entries', coalesce(v_mine, 0),
      'balance', public._giveaway_balance_of(v_me));
  end if;

  if p_quantity is null or p_quantity < 1 or p_quantity > 1000 then
    return jsonb_build_object('ok', false, 'status', 'invalid_quantity');
  end if;

  select * into g from public.giveaways where id = p_giveaway_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'status', 'not_found');
  end if;
  if g.entry_mode <> 'wallet' then
    return jsonb_build_object('ok', false, 'status', 'not_wallet_giveaway');
  end if;
  if g.status <> 'active' or (g.end_date is not null and g.end_date <= now()) then
    return jsonb_build_object('ok', false, 'status', 'closed');
  end if;

  select coalesce(sum(quantity), 0) into v_total from public.giveaway_entries where giveaway_id = g.id;
  select id, quantity into v_entry, v_mine from public.giveaway_entries where giveaway_id = g.id and user_id = v_me;
  v_mine := coalesce(v_mine, 0);

  if g.per_user_max is not null and v_mine + p_quantity > g.per_user_max then
    return jsonb_build_object('ok', false, 'status', 'per_user_cap',
      'remaining', greatest(g.per_user_max - v_mine, 0), 'my_entries', v_mine);
  end if;
  if v_total + p_quantity > g.max_entries then
    return jsonb_build_object('ok', false, 'status', 'capacity',
      'remaining', greatest(g.max_entries - v_total, 0));
  end if;

  if v_entry is null then
    if p_entrant is null
       or nullif(btrim(p_entrant->>'name_as_on_id'), '') is null
       or nullif(btrim(p_entrant->>'email'), '') is null
       or nullif(btrim(p_entrant->>'phone'), '') is null
       or nullif(p_entrant->>'birthday', '') is null
       or coalesce((p_entrant->>'agreed_to_rules')::boolean, false) is not true
       or coalesce((p_entrant->>'agreed_to_privacy')::boolean, false) is not true
       or coalesce((p_entrant->>'confirmed_age')::boolean, false) is not true then
      return jsonb_build_object('ok', false, 'status', 'entrant_details_required');
    end if;
    begin
      v_bday := (p_entrant->>'birthday')::date;
    exception when others then
      return jsonb_build_object('ok', false, 'status', 'entrant_details_required');
    end;
    if v_bday > (current_date - make_interval(years => coalesce(g.min_age, 18))) then
      return jsonb_build_object('ok', false, 'status', 'underage');
    end if;
  end if;

  -- Debit first: if the balance is short nothing else has happened.
  begin
    v_res := public._giveaway_wallet_apply(v_me, -p_quantity, 'giveaway_spend', g.id, null, v_key, v_me, null);
  exception when sqlstate 'P0001' then
    return jsonb_build_object('ok', false, 'status', 'insufficient_balance',
      'balance', public._giveaway_balance_of(v_me));
  end;
  if (v_res->>'duplicate')::boolean then          -- concurrent twin of this exact request won
    return jsonb_build_object('ok', true, 'status', 'duplicate', 'my_entries', v_mine,
      'balance', (v_res->>'balance')::int);
  end if;

  perform set_config('compete.giveaway_op', 'wallet_entry', true);
  if v_entry is null then
    insert into public.giveaway_entries (giveaway_id, user_id, name_as_on_id, birthday, email, phone,
        agreed_to_rules, agreed_to_privacy, confirmed_age, opted_in_promotions, quantity)
    values (g.id, v_me, btrim(p_entrant->>'name_as_on_id'), v_bday, lower(btrim(p_entrant->>'email')),
        btrim(p_entrant->>'phone'), true, true, true,
        coalesce((p_entrant->>'opted_in_promotions')::boolean, false), p_quantity);
  else
    update public.giveaway_entries set quantity = quantity + p_quantity where id = v_entry;
  end if;
  perform set_config('compete.giveaway_op', '', true);

  if v_total + p_quantity >= g.max_entries then
    update public.giveaways set status = 'ended', ended_at = now(), updated_at = now() where id = g.id;
    v_closed := true;
  end if;

  return jsonb_build_object('ok', true, 'status', 'entered',
    'added', p_quantity, 'my_entries', v_mine + p_quantity,
    'total_entries', v_total + p_quantity, 'capacity', g.max_entries,
    'balance', (v_res->>'balance')::int, 'closed', v_closed);
end
$function$
;

CREATE OR REPLACE FUNCTION public.draw_wallet_giveaway(p_giveaway_id integer, p_redraw_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_me      bigint := public._authz_my_id_auto();
  g         public.giveaways%rowtype;
  v_total   bigint;
  v_ticket  bigint;
  v_hash    text;
  w         record;
  v_draw_no integer;
begin
  if not public._giveaway_is_admin() then
    raise exception 'not authorized' using errcode = '42501';
  end if;

  select * into g from public.giveaways where id = p_giveaway_id for update;
  if not found then
    return jsonb_build_object('ok', false, 'status', 'not_found');
  end if;
  if g.entry_mode <> 'wallet' then
    return jsonb_build_object('ok', false, 'status', 'not_wallet_giveaway');
  end if;

  perform set_config('compete.giveaway_op', 'draw', true);

  if p_redraw_reason is not null then
    if g.status <> 'awarded' or g.winner_id is null then
      return jsonb_build_object('ok', false, 'status', 'not_awarded');
    end if;
    if nullif(btrim(p_redraw_reason), '') is null then
      return jsonb_build_object('ok', false, 'status', 'reason_required');
    end if;
    update public.giveaway_winner_history
       set status = 'disqualified', disqualified_at = now(), disqualified_by = v_me,
           disqualified_reason = btrim(p_redraw_reason)
     where giveaway_id = g.id and user_id = g.winner_id and status = 'winner';
    update public.giveaway_draws
       set invalidated = true, invalidation_reason = btrim(p_redraw_reason),
           invalidated_at = now(), invalidated_by = v_me
     where giveaway_id = g.id and winner_id = g.winner_id and coalesce(invalidated, false) = false;
    update public.profiles set total_winnings = greatest(coalesce(total_winnings, 0) - coalesce(g.prize_value, 0), 0)
     where id_auto = g.winner_id;
  elsif g.status <> 'ended' then
    return jsonb_build_object('ok', false, 'status', 'not_ended');
  end if;

  with pool as (
    select e.id, e.user_id, e.quantity
      from public.giveaway_entries e
     where e.giveaway_id = g.id
       and not exists (select 1 from public.giveaway_winner_history h
                        where h.giveaway_id = g.id and h.user_id = e.user_id and h.status = 'disqualified')
  )
  select coalesce(sum(quantity), 0),
         md5(coalesce(string_agg(id || ':' || user_id || ':' || quantity, ',' order by id), ''))
    into v_total, v_hash from pool;

  if v_total = 0 then
    return jsonb_build_object('ok', false, 'status', 'no_eligible_entries');
  end if;

  v_ticket := ((('x' || encode(extensions.gen_random_bytes(8), 'hex'))::bit(64)::bigint & 9223372036854775807) % v_total) + 1;

  select e.id, e.user_id, e.name_as_on_id, e.email, e.phone into w
    from (
      select e.*, sum(e.quantity) over (order by e.id) as upto
        from public.giveaway_entries e
       where e.giveaway_id = g.id
         and not exists (select 1 from public.giveaway_winner_history h
                          where h.giveaway_id = g.id and h.user_id = e.user_id and h.status = 'disqualified')
    ) e
   where e.upto >= v_ticket
   order by e.id
   limit 1;

  select coalesce(max(draw_number), 0) + 1 into v_draw_no from public.giveaway_draws where giveaway_id = g.id;
  insert into public.giveaway_draws (giveaway_id, drawn_by, winner_id, draw_number, entry_id,
                                     total_tickets, winning_ticket, pool_hash)
  values (g.id, v_me, w.user_id, v_draw_no, w.id, v_total, v_ticket, v_hash);

  insert into public.giveaway_winner_history (giveaway_id, user_id, entry_id, status, drawn_at, drawn_by)
  values (g.id, w.user_id, w.id, 'winner', now(), v_me);

  update public.giveaways
     set winner_id = w.user_id, winner_drawn_at = now(), winner_drawn_by = v_me, status = 'awarded',
         ended_at = coalesce(ended_at, now()), updated_at = now()
   where id = g.id;

  update public.profiles set total_winnings = coalesce(total_winnings, 0) + coalesce(g.prize_value, 0)
   where id_auto = w.user_id;

  perform set_config('compete.giveaway_op', '', true);

  return jsonb_build_object('ok', true, 'status', case when p_redraw_reason is null then 'drawn' else 'redrawn' end,
    'draw_number', v_draw_no, 'total_tickets', v_total, 'winning_ticket', v_ticket, 'pool_hash', v_hash,
    'winner', jsonb_build_object('entry_id', w.id, 'user_id', w.user_id, 'name', w.name_as_on_id,
                                 'email', w.email, 'phone', w.phone));
end
$function$
;

CREATE OR REPLACE FUNCTION public.log_referral_visit(p_code text, p_channel text DEFAULT 'web'::text, p_platform text DEFAULT 'unknown'::text, p_campaign text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_code_id  bigint;
  v_campaign text := nullif(btrim(coalesce(p_campaign, '')), '');
  v_id       uuid;
begin
  select rc.id into v_code_id
    from public.referral_codes rc
    join public.profiles p on p.id_auto = rc.profile_id
   where rc.code = upper(btrim(coalesce(p_code, '')))
     and rc.disabled_at is null
     and coalesce(p.status, 'active') = 'active'
     and not p.is_disabled
     and p.deleted_at is null;
  if v_code_id is null then
    return null;
  end if;

  if (select count(*) from public.referral_visits
       where referral_code_id = v_code_id and created_at > now() - interval '60 seconds') >= 30
     or (select count(*) from public.referral_visits
          where created_at > now() - interval '60 seconds') >= 600 then
    return null;
  end if;

  if v_campaign is not null and v_campaign !~ '^[A-Za-z0-9_.-]{1,64}$' then
    v_campaign := null;
  end if;

  insert into public.referral_visits (referral_code_id, channel, platform, campaign)
  values (v_code_id,
          case when p_channel in ('web', 'app_link', 'install_referrer') then p_channel else 'web' end,
          case when p_platform in ('ios', 'android', 'desktop', 'unknown') then p_platform else 'unknown' end,
          v_campaign)
  returning id into v_id;
  return v_id;
end
$function$
;

CREATE OR REPLACE FUNCTION public.mark_referral_visit(p_visit_id uuid, p_event text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare n int;
begin
  if p_event = 'app_open' then
    update public.referral_visits set app_opened_at = now()
     where id = p_visit_id and app_opened_at is null and created_at > now() - interval '30 days';
  elsif p_event = 'install' then
    update public.referral_visits set installed_at = now()
     where id = p_visit_id and installed_at is null and created_at > now() - interval '30 days';
  else
    return false;
  end if;
  get diagnostics n = row_count;
  return n > 0;
end
$function$
;

CREATE OR REPLACE FUNCTION public.claim_referral(p_code text, p_source text DEFAULT 'manual'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  c_window   constant interval := interval '7 days';
  v_uid      uuid := auth.uid();
  v_me       bigint;
  v_signup   timestamptz;
  v_code_id  bigint;
  v_owner    bigint;
  v_existing bigint;
  v_new_id   bigint;
  v_source   text := case when p_source in ('link', 'manual') then p_source else 'manual' end;
begin
  if v_uid is null then
    return jsonb_build_object('ok', false, 'status', 'not_authenticated');
  end if;

  select id_auto into v_me from public.profiles where id = v_uid;
  if v_me is null then
    return jsonb_build_object('ok', false, 'status', 'no_profile');
  end if;

  select rc.id, rc.profile_id into v_code_id, v_owner
    from public.referral_codes rc
    join public.profiles p on p.id_auto = rc.profile_id
   where rc.code = upper(btrim(coalesce(p_code, '')))
     and rc.disabled_at is null
     and coalesce(p.status, 'active') = 'active'
     and not p.is_disabled
     and p.deleted_at is null;
  if v_code_id is null then
    return jsonb_build_object('ok', false, 'status', 'invalid_code');
  end if;

  if v_owner = v_me then
    return jsonb_build_object('ok', false, 'status', 'self_referral');
  end if;

  -- Existing attribution wins, always (checked before the window so repeats stay idempotent).
  select referrer_profile_id into v_existing from public.referrals where referred_profile_id = v_me;
  if found then
    -- ★ Same referral re-claimed: retry a pending/failed reward (idempotent; no-op otherwise).
    if v_existing = v_owner then
      perform public._referral_try_signup_reward(r.id)
         from public.referrals r
        where r.referred_profile_id = v_me and r.reward_status in ('pending', 'failed');
    end if;
    return jsonb_build_object('ok', v_existing = v_owner,
      'status', case when v_existing = v_owner then 'already_claimed' else 'already_attributed' end);
  end if;

  -- Window measured from auth.users.created_at: server-set, unlike profiles.created_at, which the
  -- client can write on insert and on its own-row update.
  select created_at into v_signup from auth.users where id = v_uid;
  if v_signup is null or v_signup < now() - c_window then
    return jsonb_build_object('ok', false, 'status', 'window_expired');
  end if;

  if exists (select 1 from public.referrals
              where referred_profile_id = v_owner and referrer_profile_id = v_me) then
    return jsonb_build_object('ok', false, 'status', 'mutual_referral');
  end if;

  insert into public.referrals (referred_profile_id, referrer_profile_id, referral_code_id, source)
  values (v_me, v_owner, v_code_id, v_source)
  on conflict (referred_profile_id) do nothing
  returning id into v_new_id;

  if v_new_id is null then
    -- Lost a concurrent race: report what won.
    select referrer_profile_id into v_existing from public.referrals where referred_profile_id = v_me;
    return jsonb_build_object('ok', v_existing = v_owner,
      'status', case when v_existing = v_owner then 'already_claimed' else 'already_attributed' end);
  end if;

  -- ★ Referrer's +1 Giveaway Entry. Never fails the claim: attribution above is kept even if the
  -- reward step errors (it is then marked 'failed' and retried idempotently later).
  perform public._referral_try_signup_reward(v_new_id);

  return jsonb_build_object('ok', true, 'status', 'claimed');
end
$function$
;

CREATE OR REPLACE FUNCTION public._referral_issue_signup_reward(p_referral_id bigint)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  c_monthly_cap constant integer := 25;
  c_tz          constant text := 'America/Phoenix';
  v_status      text;
  v_referrer    bigint;
  v_month_start timestamptz;
  v_used        integer;
begin
  -- Lock the referral: concurrent attempts for the same referral serialize here.
  select reward_status, referrer_profile_id into v_status, v_referrer
    from public.referrals where id = p_referral_id for update;
  if not found then
    return 'not_found';
  end if;
  if v_status not in ('pending', 'failed') then
    return v_status;                         -- already decided: rewarded / capped / not_eligible
  end if;

  if v_referrer is null then                 -- referrer account deleted before the reward
    update public.referrals set reward_status = 'not_eligible', reward_decided_at = now()
     where id = p_referral_id;
    return 'not_eligible';
  end if;

  -- Serialize the monthly-cap check per referrer on their wallet row (the same row
  -- _giveaway_wallet_apply locks), so two simultaneous claims can't both take the 25th slot.
  insert into public.giveaway_wallets (profile_id) values (v_referrer) on conflict do nothing;
  perform 1 from public.giveaway_wallets where profile_id = v_referrer for update;

  v_month_start := date_trunc('month', now() at time zone c_tz) at time zone c_tz;
  select count(*) into v_used
    from public.giveaway_credit_ledger
   where profile_id = v_referrer
     and reason = 'referral_signup_reward'
     and created_at >= v_month_start;

  if v_used >= c_monthly_cap then
    update public.referrals set reward_status = 'capped', reward_decided_at = now()
     where id = p_referral_id;
    return 'capped';
  end if;

  -- Deterministic key: even if the status write were lost, a second grant is a no-op.
  perform public._giveaway_wallet_apply(
    v_referrer, 1, 'referral_signup_reward', null, p_referral_id,
    'referral_signup:' || p_referral_id, null, 'Referral signup reward');

  update public.referrals set reward_status = 'rewarded', reward_decided_at = now()
   where id = p_referral_id;
  return 'rewarded';
end
$function$
;

CREATE OR REPLACE FUNCTION public._referral_try_signup_reward(p_referral_id bigint)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_result text;
begin
  begin
    v_result := public._referral_issue_signup_reward(p_referral_id);
  exception when others then
    update public.referrals set reward_status = 'failed', reward_decided_at = now()
     where id = p_referral_id and reward_status in ('pending', 'failed');
    return 'failed';
  end;
  return v_result;
end
$function$
;
